(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["coding"]||{};var a=d["algorithms"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="alg-speculative-decoding-code"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-decoding-code-sec-1\">一 · 一次低延迟补全的时延倒挂事故</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-decoding-code-sec-2\">二 · 它精确解决的那一类问题</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-decoding-code-sec-3\">三 · 它明确不解决的问题</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-decoding-code-sec-4\">四 · 失败模式的机理拆解</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-decoding-code-sec-5\">五 · 适用边界的工程判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-decoding-code-sec-6\">六 · 边界不在“能不能加速”，而在“接受率是否撑得起验证前向”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-decoding-code-sec-7\">七 · 草稿段：前缀进入、γ 次自回归、概率随行</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-decoding-code-sec-8\">八 · 验证前向：一次并行、γ+1 个位置、KV 线性增长</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-decoding-code-sec-9\">九 · 逐位置判定：min(1,p/q) 与首次拒绝的残差采样</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-decoding-code-sec-10\">十 · KV 提交：只留接受位、丢弃拒绝位及其后</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-decoding-code-sec-11\">十一 · 轮次衔接与代价核算：接受率决定净收益</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-decoding-code-sec-12\">十二 · 验证前向的边界：接受率、γ 与 KV 回收的三条失效线</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-decoding-code-sec-13\">十三 · 期望接受长度的逐项拆解</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-decoding-code-sec-14\">十四 · 加速比公式里的 $c$ 是什么</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-decoding-code-sec-15\">十五 · 拒绝采样为何严格保持目标分布</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-decoding-code-sec-16\">十六 · 伪代码：从公式到可落地循环</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-decoding-code-sec-17\">十七 · 一轮的账：延迟、带宽与显存</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-decoding-code-sec-18\">十八 · 失败模式的公式读法</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-decoding-code-sec-19\">十九 · 接受率塌陷与 γ 失配：这套方案的收益边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-decoding-code-sec-20\">二十 · 请求形态的匹配：短前缀、短续写与低延迟 SLO</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-decoding-code-sec-21\">二十一 · 长度分布：γ 与上下文长度的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-decoding-code-sec-22\">二十二 · 并发与批大小：两份显存共同约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-decoding-code-sec-23\">二十三 · 负载不对时的三种崩法</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-decoding-code-sec-24\">二十四 · 配方表：按负载选参数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-decoding-code-sec-25\">二十五 · 负载配方：草稿验证只在“短前缀、高一致性、低并发”的窄带上赚钱</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-decoding-code-sec-26\">二十六 · 硬件档位：按验证前向的形态选卡，而不是按草稿模型</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-decoding-code-sec-27\">二十七 · 并行拓扑：草稿与目标的放置决定通信账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-decoding-code-sec-28\">二十八 · 量化方案：草稿与目标分开评估，拒绝采样的数值敏感点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-decoding-code-sec-29\">二十九 · KV 策略：只留被接受位置，拒绝即截断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-decoding-code-sec-30\">三十 · 调度参数：$\\gamma$ 是运行期变量，不是编译期常量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-decoding-code-sec-31\">三十一 · 配方边界：从硬件档位到失效条件的联调</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-decoding-code-sec-32\">三十二 · 验证前向的显存账：γ 把 KV 与激活一起放大</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-decoding-code-sec-33\">三十三 · 带宽账：摊薄的是权重读取，不是全部</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-decoding-code-sec-34\">三十四 · 通信与部署拓扑：同机、分卡、还是分离</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-decoding-code-sec-35\">三十五 · 功耗与热：γ 步自回归是持续的带宽负载</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-decoding-code-sec-36\">三十六 · 尾延迟：拒绝路径才是长尾来源</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-decoding-code-sec-37\">三十七 · 规模上去以后哪里先崩：一条判定顺序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-decoding-code-sec-38\">三十八 · 规模上去以后，先崩的是验证前向的 KV 与带宽账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-decoding-code-sec-39\">三十九 · 精度失败模式：接受率骤降与分布错位</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-decoding-code-sec-40\">四十 · 显存失败模式：γ 过大与 KV 错位导致的 OOM</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-decoding-code-sec-41\">四十一 · 调度失败模式：批抖动与路由不均</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-decoding-code-sec-42\">四十二 · 尾延迟尖刺的成因链与监控指标</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-decoding-code-sec-43\">四十三 · 回滚路径：分级降级与版本绑定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-decoding-code-sec-44\">四十四 · 失败模式与诊断：接受率塌陷、验证前向反噬与 KV 错位</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-decoding-code-sec-45\">四十五 · 对照轴：把候选算法放到同一张坐标上</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-decoding-code-sec-46\">四十六 · 决策表：按负载形态与 SLO 类型分流</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-decoding-code-sec-47\">四十七 · 适用条件的量化判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-decoding-code-sec-48\">四十八 · 与多解码头、特征级路线的取舍细节</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-decoding-code-sec-49\">四十九 · 切换与退出：什么信号出现时换算法</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-speculative-decoding-code-sec-50\">五十 · 选型边界：草稿验证何时该让位给多解码头与朴素解码</button></li></ol></nav><figure class=\"diagram\" data-fig=\"algo-flow\"><svg style=\"max-width:540px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 540.0 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"458.0\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">草稿模型基于当前前缀自回归生成 γ 个候选 token 及其概率</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"458.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">目标模型对前缀加 γ 个候选做一次并行前向，得到每个位置的验证概率</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"458.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">逐位置比较草稿概率与目标概率，按 min(1,p/q) 接受，首次拒绝处从…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"458.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">接受长度决定本轮实际推进的 token 数，KV 只保留被接受的 toke…</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"458.0\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">若全部接受则额外从目标模型采样一个 bonus token，进入下一轮</text></svg><figcaption><b>执行流程</b> · 从输入到输出的关键步骤；每一步的复杂度与坑在正文展开。</figcaption></figure>\n<h3 id=\"alg-speculative-decoding-code-sec-1\">一 · 一次低延迟补全的时延倒挂事故</h3>\n<p>某代码补全服务在灰度上线投机解码后，观测到一类反常现象：平均每 token 时延下降，但尾部时延反而抬升，部分请求的首 token 后时延比朴素自回归解码还高。定位结果是草稿模型与目标模型的 tokenizer 版本不一致——草稿侧用的是旧版分词表，同一段前缀被切成不同的 token 序列，草稿提出的候选在目标模型看来概率极低，逐位置比较时首个位置就被拒绝。于是每一轮只推进一个 token，却额外付出了一个草稿模型的自回归前向和一次目标模型的并行验证前向。验证前向的 KV 与算力按 $\\gamma$ 线性增长，而实际收益为零，这就是净损失。事故的本质不是实现 bug，而是把投机解码当成了无条件加速器：它只在草稿与目标分布足够接近、接受率足够高时才摊薄成本，否则是纯粹的加法。</p>\n<p>这个案例把本算法要解决的问题边界划得很清楚。代码补全的自回归逐 token 解码受内存带宽限制：目标模型每步只出一个 token，却要把全部权重从显存读一遍，算术强度极低。低延迟 SLO 下，吞吐与首 token 后时延互相挤压，解码步数成为主要成本项。投机解码的切入点正是“步数”——用便宜的小模型把一步扩展成多步候选，再让大模型一次前向并行验证，把多次权重读取压缩成一次。它不解决权重读取本身的带宽上限，也不解决长上下文下注意力计算的算力开销；它只是把“每 token 一次全量权重读取”摊薄到“每轮一次全量权重读取、多个 token”。因此当接受率不足时，摊薄失效，验证前向变成额外负担。</p>\n\n<h3 id=\"alg-speculative-decoding-code-sec-2\">二 · 它精确解决的那一类问题</h3>\n<p>问题的形式化表述是：给定前缀，目标模型 $p$ 的自回归解码每步采样一个 token，步与步之间无法并行，因为下一步依赖上一步的输出。解码的瓶颈不在浮点算力，而在把权重从 HBM 搬到 SM 的带宽。投机解码把这条串行链改成“草稿串行、验证并行”：草稿模型基于当前前缀自回归生成 $\\gamma$ 个候选 token 及其概率 $q$，目标模型对前缀加 $\\gamma$ 个候选做一次并行前向，得到每个位置的验证概率 $p$。一次目标前向覆盖 $\\gamma+1$ 个位置，权重只读一遍，这就是它摊薄带宽的物理基础。</p>\n<p>收益的上界由接受长度决定。若每个位置独立地以 $\\min(1,p_j/q_j)$ 的概率被接受，则一轮推进的期望 token 数为</p>\n<div class=\"formula\">$$\\mathbb{E}[\\text{tokens/round}]=\\sum_{i=1}^{\\gamma+1}\\prod_{j=1}^{i}\\min\\left(1,\\frac{p_j}{q_j}\\right),\\quad \\text{speedup}\\approx\\frac{\\mathbb{E}[\\text{accept}]}{c\\cdot\\gamma+1}$$</div>\n<p>其中 $c$ 是草稿模型单步前向相对目标模型的成本比。这个式子直接给出适用边界：分子是接受长度，分母是每轮付出的验证成本加草稿成本。当 $p$ 与 $q$ 接近，$\\min(1,p/q)$ 接近 1，期望接受长度接近 $\\gamma+1$，加速比可观；当两者偏离，接受长度塌缩到 1 附近，分母却仍含 $c\\cdot\\gamma$，加速比小于 1。代码补全之所以是它的主场，是因为续写形态高度规整——缩进、括号闭合、常见 API 调用序列——草稿模型在这些位置上的分布与目标模型高度重合，接受率高。这是任务结构带来的红利，不是算法本身的普适性质。</p>\n\n<h3 id=\"alg-speculative-decoding-code-sec-3\">三 · 它明确不解决的问题</h3>\n<p>第一，它不降低单次目标前向的成本。验证前向要处理 $\\gamma+1$ 个位置，KV 与算力随 $\\gamma$ 线性增长；在长上下文场景下，注意力部分的算力占比上升，验证前向本身可能成为新的瓶颈，此时增大 $\\gamma$ 只提升理论上限，实际吞吐反被验证占满。第二，它不改善首 token 时延（TTFT）。投机解码作用于解码阶段，预填阶段的前缀计算不受影响，分离式预填/解码的收益与它是正交的两件事。第三，它不解决显存容量问题。草稿模型额外占用显存与算力，需与目标模型同机部署或分卡部署，批大小受两者显存共同约束；在显存紧张的部署里，草稿模型挤占的 KV 空间可能抵消吞吐收益。第四，它不提供分布之外的任何正确性增强——拒绝采样保证输出分布与目标模型严格一致，但若目标模型本身有偏，投机解码只是忠实地复现这个偏。</p>\n<p>还有一类常被误认的边界：草稿与目标 tokenizer 或分布不一致会拉低接受率，这不是调参能修的，是选型问题。草稿模型可以独立选型是它的部署优势，但也是它的脆弱点——两模型分布一致性约束是硬约束，任何分词表、词表裁剪、量化精度的差异都会直接反映到 $\\min(1,p/q)$ 上。量化需分别评估草稿与目标模型精度，草稿侧量化过激会让 $q$ 偏离 $p$，接受率骤降。</p>\n\n<h3 id=\"alg-speculative-decoding-code-sec-4\">四 · 失败模式的机理拆解</h3>\n<p>三类失败模式各有明确的机理。其一，分布不一致导致的接受率骤降：$\\min(1,p_j/q_j)$ 在 $q_j$ 远大于 $p_j$ 的位置上取值很小，首个位置即拒绝，一轮只推进一个 token，而验证前向的 KV 与算力已按 $\\gamma$ 付出，时延高于朴素解码。其二，$\\gamma$ 固定过大：验证前向的 KV 与算力线性增长，长上下文下显存与算力被验证占满，吞吐下降；$\\gamma$ 应按任务统计接受率动态调，而不是取一个全局常数。其三，KV 错位：拒绝后未正确丢弃被拒位置及其后的草稿 KV，后续轮次的前缀与 token 序列不一致，输出出现重复或乱序——这是最隐蔽的一类，因为单轮输出看似正常，错误在几轮之后才累积显现。</p>\n<p>KV 管理的正确做法是只保留被接受 token 对应位置的 KV，被拒绝位置及其后的草稿 KV 全部丢弃；若 $\\gamma$ 个候选全部接受，则额外从目标模型采样一个 bonus token 进入下一轮。bonus token 的 KV 也要在下一轮前写入，否则下一轮验证前向的前缀会缺一个位置。这套账在分页 KV 块管理下要按块粒度对齐，跨块边界的部分接受会让块内出现空洞，需要块表重排——这是把投机解码接入生产栈时最容易出问题的地方，也是它与分页 KV 块表管理必须联合设计的理由。</p>\n\n<h3 id=\"alg-speculative-decoding-code-sec-5\">五 · 适用边界的工程判据</h3>\n<p>判断一个负载是否该上投机解码，看三个量：接受率、草稿成本比 $c$、$\\gamma$ 的边际收益。接受率可从线上采样统计，按任务分桶——代码补全、工具调用、结构化输出各自不同，混在一起统计会掩盖低接受率桶的净损失。$c$ 由草稿模型规模与目标模型规模之比决定，草稿越大接受率越高但 $c$ 越大，存在最优点。$\\gamma$ 的边际收益由上面的期望公式给出：$\\gamma$ 增大时分子趋近饱和，分母线性增长，最优点在饱和点之前。</p>\n<p>部署配方上，请求形态是低延迟代码补全，前缀短、续写短，SLO 以首 token 后时延与每 token 时延为主，批大小受草稿与目标模型显存共同约束。这类负载适合投机解码，因为前缀短意味着验证前向的 KV 压力小，续写短意味着 $\\gamma$ 不必取大。反过来，长上下文、高并发、显存紧张的负载，验证前向的 KV 与算力增长会吃掉收益，应优先考虑其他路径。与多解码头投机的差别也在这里：后者不引入第二个模型，用目标模型隐状态挂轻量头，没有分布一致性约束，但草稿质量受限于头的能力；草稿验证依赖独立草稿模型，部署复杂度更高但草稿可独立选型。选哪条路取决于团队能否承担两模型的部署与一致性维护成本。</p>\n<p>最后落到一个具体机制判断：投机解码的收益不是“开了就快”，而是“接受率乘以 $\\gamma$ 摊薄后的带宽节省，减去草稿与验证的额外成本”。在代码补全这类分布高度规整的任务上，这个差值为正且可观；在接受率低或 $\\gamma$ 过大的配置下，差值为负。工程上应把接受率作为一等监控指标，按桶动态调 $\\gamma$，并把 KV 丢弃与 bonus token 写入做成不变量校验，否则事故不会以报错形式出现，而是以时延倒挂和输出乱序的形式出现。</p>\n\n<h3 id=\"alg-speculative-decoding-code-sec-6\">六 · 边界不在“能不能加速”，而在“接受率是否撑得起验证前向”</h3>\n<p>把草稿验证当成一个无条件开关，是线上最常见的事故来源。典型形态是：代码补全服务原本逐 token 解码，单步只出一个 token，解码步数被内存带宽卡死，首 token 后时延压不进 SLO；团队接入草稿模型后，压测环境接受率好看，上线后却出现长尾请求时延反超朴素解码。根因往往不是草稿模型太慢，而是草稿与目标模型的 tokenizer 或分布不一致——分词边界不同、词表映射错位、草稿在特定前缀上系统性偏向另一类补全，逐位置比较时 $\\min(1,p/q)$ 大量落到拒绝分支。此时每一轮都要付出目标模型一次并行前向的完整代价，却只推进极少 token，验证开销从“摊薄带宽”变成“净损失”。这个算法解决的是解码步数主导的成本问题，不解决目标模型单次前向本身过慢、不解决前缀极长导致的注意力开销、也不解决批调度与显存碎片——那些属于别的层面。</p>\n<p>收益的解析边界可以直接写出来。设草稿每步开销相对目标模型单步的比值为 $c$，候选长度 $\\gamma$，则一轮的期望推进量与加速比近似为</p>\n<div class=\"formula\">$$\\mathbb{E}[\\text{tokens/round}]=\\sum_{i=1}^{\\gamma+1}\\prod_{j=1}^{i}\\min\\left(1,\\frac{p_j}{q_j}\\right),\\quad \\text{speedup}\\approx\\frac{\\mathbb{E}[\\text{accept}]}{c\\cdot\\gamma+1}$$</div>\n<p>分母说明了一切：$\\gamma$ 每加一，验证前向的 KV 与算力就线性增长一截，而分子只在接受率支撑下才增长。接受率低时分子趋近于 1，分母却随 $\\gamma$ 膨胀，加速比跌破 1——这就是“收益转负”的定量含义。因此固定大 $\\gamma$ 是危险的默认值：长上下文请求下，验证前向要为目标模型保留前缀加 $\\gamma$ 个候选位置的 KV，显存与算力被验证占满，吞吐反而下降。工程判断是按任务统计接受率动态调 $\\gamma$，而不是拍一个上限。</p>\n<p>适用边界由此收敛得很清楚。它适合前缀短、续写短、草稿与目标分布高度一致的场景，例如低延迟代码补全：接受率高时一轮推进多个 token，摊薄目标模型权重读取带宽，解码步数成倍下降，且拒绝采样保证输出分布与目标模型严格一致，对正确性敏感的工具调用与代码生成可以放心用。它不适合接受率天然低的开放式生成，也不适合草稿模型显存与目标模型同机争抢、批大小被两者共同约束的部署。还有一个隐蔽的失效条件：拒绝后若未正确丢弃被拒位置及其后的草稿 KV，后续轮次 KV 与 token 错位，输出出现重复或乱序——这类 bug 不体现在接受率指标上，只体现在下游任务成功率上，必须把 KV 截断当作验证路径的强制步骤来测。</p>\n<table class=\"mini\"><thead><tr><th>条件</th><th>系统表现</th><th>工程动作</th></tr></thead><tbody><tr><td>接受率高、$\\gamma$ 适中</td><td>解码步数下降，带宽摊薄</td><td>维持当前 $\\gamma$，监控接受率漂移</td></tr><tr><td>tokenizer/分布不一致</td><td>验证前向成净损失，时延长尾恶化</td><td>对齐词表与分词，按任务重估草稿选型</td></tr><tr><td>$\\gamma$ 固定过大、上下文长</td><td>验证 KV 与算力线性膨胀，吞吐下降</td><td>按上下文长度与接受率联合调 $\\gamma$</td></tr></tbody></table>\n<h3 id=\"alg-speculative-decoding-code-sec-7\">七 · 草稿段：前缀进入、γ 次自回归、概率随行</h3>\n<p>一轮投机解码的起点是当前已确认前缀 \\(x_{1..t}\\)，它对应目标模型 KV cache 中长度为 \\(t\\) 的已提交块。草稿模型拿到的输入就是这个前缀（连同其自身 KV 状态），输出是 \\(\\gamma\\) 个候选 token \\(d_1,\\dots,d_\\gamma\\) 以及每个位置上的草稿分布 \\(q_i(\\cdot)\\)。注意这里草稿段是<strong>串行自回归</strong>的：第 \\(i\\) 个候选必须等第 \\(i-1\\) 个采样完成才能生成，因此草稿段本身并不省解码步数，它省的是目标模型的前向次数。草稿段每步只做一次小模型前向加一次采样，单步代价由草稿模型权重读取带宽主导，与目标模型相比通常小一个量级以上，这是整个机制成立的前提。</p>\n<p>工程上草稿段要输出三样东西才能进入验证：候选 token 序列、逐位置的 \\(q_i\\) 概率（至少是被采样 token 处的概率，实践中常取完整 logits 以便残差采样）、以及草稿模型在这 \\(\\gamma\\) 步中产生的 KV。第三样是后面 KV 管理的伏笔——草稿 KV 与目标 KV 是两套独立的缓存，验证阶段只复用目标侧的位置，草稿侧 KV 在拒绝发生后即作废。草稿段的显存代价是常驻的：草稿模型权重、草稿 KV、以及为 \\(\\gamma\\) 步预留的激活缓冲，都要与目标模型同机共存，这直接压缩了可用的批大小。</p>\n<p>一个具体形态：低延迟代码补全请求，前缀是编辑器里已敲的几十行，续写目标是一小段函数体。草稿模型基于该前缀连续吐出 \\(\\gamma\\) 个候选 token，每步采样一次；若中途草稿自身已进入低置信区间（分布熵高），继续硬凑 \\(\\gamma\\) 步只会给验证段送低质量候选，接受率被拉低。因此草稿段的退出条件不一定是固定 \\(\\gamma\\)，可以按草稿累积置信度提前截断，把 \\(\\gamma\\) 变成动态量——这与后面按接受率调 \\(\\gamma\\) 是同一件事的两端。</p>\n\n<h3 id=\"alg-speculative-decoding-code-sec-8\">八 · 验证前向：一次并行、γ+1 个位置、KV 线性增长</h3>\n<p>验证段把前缀加 \\(\\gamma\\) 个候选拼成一个长度 \\(t+\\gamma\\) 的序列，送进目标模型做<strong>一次</strong>前向。由于因果注意力，这一次前向在每个候选位置上给出的分布 \\(p_i\\) 只依赖该位置之前的内容，恰好就是目标模型“如果逐 token 解码到该位置”会得到的分布——这是并行验证在数学上等价于串行解码的根据。输入是拼接序列与目标侧已有 KV，输出是 \\(\\gamma\\) 个位置的验证分布 \\(p_1,\\dots,p_\\gamma\\)，外加一个额外位置（第 \\(\\gamma+1\\) 个）的分布，供 bonus token 使用。</p>\n<p>代价在这里集中体现。验证前向的计算量与 KV 增量都随 \\(\\gamma\\) 线性增长：注意力部分要处理 \\(\\gamma\\) 个新 query 对 \\(t+\\gamma\\) 个 key 的交互，FFN 与投影则按 \\(\\gamma\\) 个 token 摊开。对短前缀的代码补全，\\(t\\) 不大，\\(\\gamma\\) 增大主要吃算力；对长上下文请求，\\(t\\) 很大，\\(\\gamma\\) 个新位置仍要读整条 KV，带宽代价随 \\(\\gamma\\) 放大。更关键的是显存：验证阶段必须为这 \\(\\gamma\\) 个位置同时持有激活与中间 KV，若 \\(\\gamma\\) 固定过大，这部分预留会挤占并发批的空间，吞吐反而下降。这就是“\\(\\gamma\\) 增大提升理论上限但验证前向的 KV 与算力线性增长”的具体落点。</p>\n<div class=\"formula\">$$\\text{speedup}\\approx\\frac{\\mathbb{E}[\\text{accept}]}{c\\cdot\\gamma+1}$$</div>\n<p>公式里 \\(c\\) 是草稿段单步代价相对目标段单步代价的比例。\\(\\gamma\\) 增大时分子（期望接受 token 数）增长但趋于饱和，分母线性增长，最优 \\(\\gamma\\) 落在两者斜率相等处。工程判断：不要按“越大越好”设 \\(\\gamma\\)，而应按任务实测的接受率曲线找拐点，并对不同请求形态（前缀长度、续写长度）分别设值。</p>\n\n<h3 id=\"alg-speculative-decoding-code-sec-9\">九 · 逐位置判定：min(1,p/q) 与首次拒绝的残差采样</h3>\n<p>验证分布拿到后，判定按位置从左到右串行进行——这一步是纯标量运算，代价可忽略，但顺序不可乱。对第 \\(i\\) 个位置，抽一个均匀随机数 \\(u\\)，若 \\(u&lt;\\min(1,p_i(d_i)/q_i(d_i))\\) 则接受 \\(d_i\\)，继续看第 \\(i+1\\) 个；一旦拒绝，立即停止，并在该位置从残差分布采样一个修正 token 替代 \\(d_i\\)。残差分布为</p>\n<div class=\"formula\">$$\\max(0,\\,p_i-q_i)\\ \\text{归一化}$$</div>\n<p>这一步是正确性保证的核心：拒绝采样使得最终吐出的 token 边缘分布严格等于目标分布 \\(p\\)，无论草稿 \\(q\\) 多差。也就是说草稿模型只影响效率，不影响正确性——这正是它能用于对正确性敏感的代码生成与工具调用的原因。判定段的输出是本轮实际推进的 token 序列：前 \\(k\\) 个被接受的候选加上（若有拒绝）一个修正 token；若 \\(\\gamma\\) 个全接受，则从第 \\(\\gamma+1\\) 个位置的 \\(p\\) 再采一个 bonus token，本轮推进 \\(\\gamma+1\\) 个 token。</p>\n<p>期望推进长度由接受概率连乘给出：</p>\n<div class=\"formula\">$$\\mathbb{E}[\\text{tokens/round}]=\\sum_{i=1}^{\\gamma+1}\\prod_{j=1}^{i}\\min\\left(1,\\frac{p_j}{q_j}\\right)$$</div>\n<p>这个式子说明接受率是逐位置衰减的：即使单步接受率很高，连乘到第 \\(\\gamma\\) 位也会显著下降，所以尾部候选的边际收益很低。工程含义是 \\(\\gamma\\) 的有效长度由“接受率衰减到接近零”的位置决定，而不是由显存能塞下多少决定。一个具体例子：代码补全中缩进、括号、常见 API 名这类高确定性 token 的 \\(p/q\\) 接近 1，接受顺畅；一旦进入自由命名的标识符，\\(q\\) 与 \\(p\\) 分叉，首个拒绝往往就出现在这里，本轮推进长度被截断在几位。</p>\n\n<h3 id=\"alg-speculative-decoding-code-sec-10\">十 · KV 提交：只留接受位、丢弃拒绝位及其后</h3>\n<p>判定完成后，目标侧 KV 的提交必须精确对齐接受长度。验证前向已经为 \\(t+1\\) 到 \\(t+\\gamma\\) 这 \\(\\gamma\\) 个位置算出了 KV，但只有前 \\(k\\) 个（被接受的位置）加上修正 token 所在位置是有效的；被拒绝位置及其之后的所有草稿 KV 必须丢弃，不能留在缓存里。这一步的输入是验证阶段产生的 KV 块与接受长度 \\(k\\)，输出是长度变为 \\(t+k+1\\)（或全接受时 \\(t+\\gamma+1\\)）的已提交 KV。代价是块表更新与可能的块回收：分页管理下，被丢弃的尾部块要么整块释放，要么把块内有效前缀保留、截断尾部——后者需要块内偏移的精确记账。</p>\n<p>失败模式就藏在这里：若拒绝后未正确丢弃被拒位置及其后的草稿 KV，下一轮草稿模型会基于一条“含已作废 token”的前缀继续提议，目标模型验证时看到的前缀与草稿看到的不一致，KV 与 token 错位，输出出现重复或乱序。这类错误不触发分布偏差告警，却直接破坏正确性，排查成本高。工程上应把“接受长度”作为 KV 提交的唯一权威输入，块表更新与 token 序列追加在同一事务里完成，避免两者短暂不一致。</p>\n<p>草稿侧的 KV 同样要处理：本轮草稿模型为 \\(\\gamma\\) 步算出的 KV 中，只有与接受前缀对齐的部分能在下一轮复用，其余作废。若草稿模型与目标模型共享 tokenizer 且前缀一致，草稿 KV 可以在接受长度处截断后继续用；否则每轮草稿段都要从已提交前缀重新起算，草稿段的串行成本就完全暴露在关键路径上。</p>\n\n<h3 id=\"alg-speculative-decoding-code-sec-11\">十一 · 轮次衔接与代价核算：接受率决定净收益</h3>\n<p>一轮结束后，已提交前缀更新，草稿模型从新前缀继续提议，进入下一轮。整个循环的关键路径是：草稿段串行 \\(\\gamma\\) 步 → 目标验证一次前向 → 判定与 KV 提交。每轮的时间代价近似为 \\(\\gamma\\cdot c_{\\text{draft}}+c_{\\text{verify}}+c_{\\text{commit}}\\)，推进 \\(\\mathbb{E}[\\text{accept}]\\) 个 token；朴素解码推进同样 token 数需要 \\(\\mathbb{E}[\\text{accept}]\\) 次目标前向。净收益的条件是</p>\n<div class=\"formula\">$$\\frac{\\mathbb{E}[\\text{accept}]}{\\gamma\\cdot c_{\\text{draft}}+c_{\\text{verify}}}&gt;\\frac{1}{c_{\\text{verify}}}\\ \\Longleftrightarrow\\ \\mathbb{E}[\\text{accept}]&gt;1+\\gamma\\cdot\\frac{c_{\\text{draft}}}{c_{\\text{verify}}}$$</div>\n<p>接受率低时右边不等式不成立，验证开销反成净损失，时延高于朴素解码——这是本机制最典型的失败形态。因此运行时必须按任务统计接受率并动态调 \\(\\gamma\\)：接受率高的请求形态（模板化代码、工具调用参数）放大 \\(\\gamma\\)，接受率低的（开放式续写、自由文本）收缩甚至关闭投机。另一个失败源是草稿与目标 tokenizer 或分布不一致，接受率骤降，同样落入净损失区间；这类不一致在部署时就要用同一 tokenizer 校验，而不是靠运行时调参兜。</p>\n<p>显存与带宽的账要分开算。带宽侧，投机解码摊薄的是目标模型权重读取：一次验证前向读一遍权重却推进多个 token，权重读取次数按接受长度摊薄。显存侧，草稿模型权重与草稿 KV 是净增开销，与目标模型同机部署时直接压缩批大小；分卡部署则把草稿段串行延迟加到关键路径上，跨卡通信代价进入每轮时间。工程判断：低延迟代码补全这类前缀短、续写短、接受率高的形态，同机部署加动态 \\(\\gamma\\) 是默认配方；长上下文或接受率不确定的形态，先小 \\(\\gamma\\) 试跑并采集接受率分布，再决定是否值得常驻草稿模型。</p>\n\n<h3 id=\"alg-speculative-decoding-code-sec-12\">十二 · 验证前向的边界：接受率、γ 与 KV 回收的三条失效线</h3>\n<p>草稿验证的收益不是无条件成立的，它由一条简单的比值关系支配：每一轮推进的期望 token 数除以该轮的真实代价。设草稿每 token 代价为 c（相对目标模型单步代价归一化），则 <span class=\"formula\">$$\\text{speedup}\\approx\\frac{\\mathbb{E}[\\text{accept}]}{c\\cdot\\gamma+1}$$</span> 这个式子的含义比它看起来更尖锐——分母里的 1 是目标模型那次并行验证前向，它不随接受长度缩短；分子是期望接受长度。当接受率跌到使分子接近分母时，加速比趋近 1，而草稿模型的显存与算力已经付出去了，净效果是负的。这就是第一条失效线：<strong>接受率不足时，验证开销是纯损失</strong>。代码补全场景之所以是这套机制的甜点区，正因为前缀短、续写短、目标分布与草稿分布贴近，接受率高；一旦任务换成开放式生成或跨语言续写，两模型分布漂移，接受率骤降，时延反而高于朴素解码。</p>\n<p>第二条线在 γ 上。γ 增大抬高理论上限，但目标模型验证前向的 KV 与算力随 γ 线性增长：一次前向要覆盖前缀加 γ 个候选位置，KV 写入量与注意力计算量都按 γ 扩张。长上下文下，这段验证 KV 会与常规解码 KV 争抢同一块显存池，批大小被压缩，吞吐下降。工程上应把 γ 当作按任务统计接受率后动态调整的量，而不是固定超参；固定过大的 γ 在长上下文请求上表现为显存被验证占满、有效批变小、每 token 时延抖动。</p>\n<p>第三条线是 KV 回收的正确性。接受长度决定本轮实际推进的 token 数，KV 只保留被接受 token 对应位置，被拒位置及其后的草稿 KV 必须丢弃。若丢弃逻辑写错——例如按候选总数而非接受长度截断，或 bonus token 的 KV 未按新位置写入——后续轮次的前缀与 KV 就会错位，输出出现重复或乱序，且这种错误不会触发任何数值异常，只在长序列上缓慢暴露。下表按数据流列出各步骤的输入、输出与代价归属：</p>\n<table class=\"mini\"><thead><tr><th>步骤</th><th>输入</th><th>输出</th><th>主要代价</th></tr></thead><tbody><tr><td>草稿自回归</td><td>当前前缀、草稿 KV</td><td>γ 个候选 token 及 q</td><td>γ 次串行小模型前向，显存常驻</td></tr><tr><td>目标并行验证</td><td>前缀 + γ 候选</td><td>各位置 p</td><td>一次前向，KV 与算力随 γ 线性增长</td></tr><tr><td>逐位接受/修正</td><td>p、q</td><td>接受长度、修正 token</td><td>轻量，无 GPU 密集算子</td></tr><tr><td>KV 截断与 bonus</td><td>接受长度</td><td>回收后的 KV、bonus token</td><td>显存写回与索引修正，错则全轮失效</td></tr></tbody></table>\n<p>还有一条常被忽略的边界：草稿与目标模型 tokenizer 或分布不一致时，q 与 p 不在同一 token 空间上比较，min(1,p/q) 的语义失效，接受率骤降且修正采样落在错误的残差分布上。部署上两模型可同机或分卡，但量化必须分别评估——草稿模型量化过激会系统性偏移 q，把接受率拖到失效线以下。判断这套方案是否值得上，先测目标任务上的实测接受率与 γ 的乘积关系，再看显存余量能否容纳草稿模型常驻；两项任一不满足，就该退回单模型解码或改走多解码头路线。</p>\n<h3 id=\"alg-speculative-decoding-code-sec-13\">十三 · 期望接受长度的逐项拆解</h3>\n<p>核心公式的第一项不是装饰，它把“一轮能推进多少 token”写成了逐位置概率的连乘：</p>\n<div class=\"formula\">$$\\mathbb{E}[\\text{tokens/round}]=\\sum_{i=1}^{\\gamma+1}\\prod_{j=1}^{i}\\min\\left(1,\\frac{p_j}{q_j}\\right)$$</div>\n<p>逐项读：外层求和的下标 $i$ 表示“本轮至少接受前 $i$ 个候选”这一事件，内层连乘是这 $i$ 个位置全部被接受的联合概率。第 $i$ 项之所以是连乘而非单点概率，是因为拒绝采样是逐位置串行判定的——第 $j$ 个位置被接受的前提是前 $j-1$ 个位置都已被接受，一旦某处拒绝，其后候选全部作废。因此“推进 $i$ 个 token”的概率恰为前 $i$ 个 $\\min(1,p_j/q_j)$ 之积。求和上界取到 $\\gamma+1$，是因为 $\\gamma$ 个候选全被接受时还会从目标模型额外采一个 bonus token，这一项的概率就是 $\\gamma$ 个位置的连乘，不再乘新的比值。</p>\n<p>推导的关键一步在于把“接受”写成伯努利事件并做条件分解。设 $A_j$ 为第 $j$ 位接受，则 $\\Pr[A_j\\mid A_{&lt;j}]=\\min(1,p_j/q_j)$——这个条件概率与 $A_{&lt;j}$ 无关，因为拒绝采样在每个位置的判定只依赖该位置的 $p_j,q_j$ 与一个独立均匀随机数。于是 $\\Pr[A_1\\cdots A_i]=\\prod_{j\\le i}\\Pr[A_j]$，连乘成立。反过来，若把 $\\min(1,p/q)$ 误当成边际接受率而直接相加，会高估期望长度：接受率高的位置被后面的低接受位置拖累，这正是长候选链收益衰减的数学根源。</p>\n<p>工程含义直接落在 $\\gamma$ 的选取上。期望长度随 $\\gamma$ 单调增但有上界 $1/(1-\\bar a)$（$\\bar a$ 为平均单点接受率），而验证前向的算力与 KV 随 $\\gamma$ 线性增长，于是存在一个使“每 token 摊销成本”最小的 $\\gamma$。代码补全场景前缀短、续写短，接受率通常高于开放域对话，$\\gamma$ 可以取得更大；一旦实测接受率下滑，继续加大 $\\gamma$ 只是把算力喂给被丢弃的候选。</p>\n\n<h3 id=\"alg-speculative-decoding-code-sec-14\">十四 · 加速比公式里的 $c$ 是什么</h3>\n<div class=\"formula\">$$\\text{speedup}\\approx\\frac{\\mathbb{E}[\\text{accept}]}{c\\cdot\\gamma+1}$$</div>\n<p>分母刻画一轮的总代价：验证前向处理 $\\gamma$ 个候选位置的相对成本是 $c\\cdot\\gamma$，那个 $+1$ 是本轮必然发生的那一步目标模型前向（含 bonus token 的采样）。分子是一轮实际推进的 token 数。把朴素解码的“每 token 一次前向”作为基准 1，则加速比就是“推进量除以代价”。</p>\n<p>$c$ 是这套推导里最容易被忽略又最决定成败的量：它衡量“验证一个草稿位置”相对于“朴素解码一个 token”的成本比。理想情况下验证是并行的，$c$ 远小于 1，因为一次前向的权重读取带宽被 $\\gamma$ 个位置摊薄；但 $c$ 不会趋近于 0——注意力在候选位置上要各自算 KV、要写 TMEM、要做 logits 比较，$\\gamma$ 增大时验证前向的 KV 与算力线性增长，$c$ 随之抬升。当 $c\\cdot\\gamma$ 逼近甚至超过分子时，加速比跌破 1，验证开销变成净损失。这就是“接受率低时反而更慢”的定量表达：分子缩水、分母不变。</p>\n<p>把两式联立可得一个可操作的判据：只有当 $\\mathbb{E}[\\text{accept}]&gt;c\\cdot\\gamma+1$ 时投机才有正收益。以代码补全为例，若实测单点接受率使期望推进明显大于 1，而验证前向因并行摊薄使 $c$ 保持在低位，则加速比为正；反之在分布漂移的请求上，$\\mathbb{E}[\\text{accept}]$ 掉到 1 附近，分母却仍是 $c\\gamma+1$，此时应立刻把 $\\gamma$ 调回 1 或关闭投机。这个判据不需要绝对数字，只需要在线上按任务分桶统计 $\\mathbb{E}[\\text{accept}]$ 与验证前向耗时。</p>\n\n<h3 id=\"alg-speculative-decoding-code-sec-15\">十五 · 拒绝采样为何严格保持目标分布</h3>\n<p>逐位置接受概率取 $\\min(1,p/q)$，拒绝时从残差分布 $\\max(0,p-q)$ 归一化后采样，这两步合起来使最终 token 的边缘分布恰为 $p$。推导的一步是分类讨论：对某个 token $x$，它被接受产出的概率是 $q(x)\\cdot\\min(1,p(x)/q(x))=\\min(q(x),p(x))$；它作为拒绝后的修正被产出的概率是（被拒的总概率）乘以残差归一化后的质量。被拒总概率为 $1-\\sum_x\\min(q(x),p(x))=\\sum_x\\max(0,p(x)-q(x))$，恰好等于残差分布的未归一化总质量，两者相消后修正项贡献 $\\max(0,p(x)-q(x))$。相加得 $\\min(q,p)+\\max(0,p-q)=p(x)$。</p>\n<p>这一步的工程价值在于：它把“草稿模型不准”从正确性问题降级为性能问题。草稿分布 $q$ 与目标分布 $p$ 差得再远，输出分布仍严格等于 $p$，因此该机制可用于对正确性敏感的代码生成与工具调用，不引入分布偏差。代价体现在期望长度上——$q$ 偏离 $p$ 时 $\\min(1,p/q)$ 变小，接受率下降，加速比公式的分子缩水。所以草稿模型的选型标准不是“生成质量好”，而是“与目标模型的分布一致”，tokenizer 不一致会直接让 $q$ 与 $p$ 错位，接受率骤降。</p>\n<p>数值实现上有一处必须小心：残差分布 $\\max(0,p-q)$ 在浮点下可能全为零（当 $q$ 在每个位置都支配 $p$ 时理论上不会，但量化后的 logits 可能触发）。工程上要留一个回退分支，检测到残差质量和为零时直接从 $p$ 采样，避免除零或采出非法 token。这个分支在 NVFP4/FP8 量化的草稿模型上更容易被触发，因为量化误差会让 $q$ 的概率质量分布变形。</p>\n\n<h3 id=\"alg-speculative-decoding-code-sec-16\">十六 · 伪代码：从公式到可落地循环</h3>\n<p>把三节的内容压成一段可实现的主循环，关键在于三件事：并行验证一次前向拿全 $\\gamma$ 个位置的 $p$、逐位置判定并记录首个拒绝点、按接受长度裁剪 KV。</p>\n<ul>\n<li>草稿阶段：以当前前缀为输入，草稿模型自回归跑 $\\gamma$ 步，缓存每步的 $q_j$ 与候选 token；这 $\\gamma$ 步是串行的，是投机延迟的下界。</li>\n<li>验证阶段：把前缀拼接 $\\gamma$ 个候选，目标模型一次前向，取出 $\\gamma$ 个验证位置的 $p_j$；这一次前向的 KV 写入量随 $\\gamma$ 线性增长。</li>\n<li>判定阶段：对 $j=1..\\gamma$ 依次抽 $u_j\\sim U(0,1)$，若 $u_j\\le\\min(1,p_j/q_j)$ 则接受并继续，否则在 $j$ 处停，从 $\\max(0,p_j-q_j)$ 归一化分布采一个修正 token 追加，本轮结束。</li>\n<li>收尾阶段：若 $\\gamma$ 个全接受，从目标模型最后位置的分布采一个 bonus token；随后把 KV 裁剪到“前缀 + 实际接受序列”的长度，丢弃被拒位置及其后的草稿 KV。</li>\n</ul>\n<p>伪代码里最容易写错的是 KV 裁剪的边界。目标模型验证前向已经为 $\\gamma$ 个候选位置写了 KV，但只有前 $k$ 个（$k$ 为接受长度）是有效的；被拒位置 $k+1$ 及其后的 KV 必须丢弃，否则下一轮把新草稿拼到错误的历史上，输出会出现重复或乱序。实现上应让 KV 的写入长度由接受长度驱动，而不是由验证前向的输入长度驱动——这要求验证前向的 KV 布局支持按位置截断，分页 KV 块管理在这里承担了裁剪的物理落地。</p>\n<p>性能上，这段循环的瓶颈分布很清晰：草稿阶段 $\\gamma$ 步串行受内存带宽限制，验证阶段一次前向受算力与 KV 带宽限制，判定阶段是纯 CPU/轻量 GPU 操作可忽略。因此端到端时延约等于“$\\gamma$ 次草稿解码 + 一次验证前向 + 采样开销”，与加速比公式的分母同构。</p>\n\n<h3 id=\"alg-speculative-decoding-code-sec-17\">十七 · 一轮的账：延迟、带宽与显存</h3>\n<p>把一轮拆成三段记账。草稿段：$\\gamma$ 次串行前向，每次都要读一遍草稿模型权重，延迟随 $\\gamma$ 线性增长，这是投机无法消除的固定开销，也是草稿模型必须足够小的原因。验证段：一次前向处理 $\\gamma+1$ 个位置，权重读取被摊薄，但 KV 写入与注意力计算随 $\\gamma$ 线性增长；在长上下文下，验证前向的 KV 带宽会先于算力成为瓶颈，$\\gamma$ 过大使显存与算力被验证占满，吞吐下降。判定与采样段：可忽略。</p>\n<table class=\"mini\"><thead><tr><th>阶段</th><th>随 $\\gamma$ 的增长</th><th>主要资源</th><th>工程约束</th></tr></thead><tbody><tr><td>草稿自回归</td><td>线性（串行步数）</td><td>草稿模型权重带宽、草稿 KV 显存</td><td>草稿模型额外占用显存与算力，需与目标模型同机或分卡部署</td></tr><tr><td>目标验证前向</td><td>线性（KV 与算力）</td><td>目标模型算力、KV 带宽</td><td>$\\gamma$ 增大时验证 KV 线性增长，长上下文下先撞带宽墙</td></tr><tr><td>判定与修正采样</td><td>近似常数</td><td>轻量 GPU 核</td><td>残差分布需防零质量回退</td></tr></tbody></table>\n<p>显存账要单独算：草稿模型与目标模型同时驻留，批大小受两者显存共同约束；草稿 KV 与目标 KV 都要为 $\\gamma$ 个候选位置预留空间，$\\gamma$ 越大预留越多，而其中大部分在拒绝时被丢弃，属于“为不确定性付费”。这就是为什么 $\\gamma$ 必须按任务接受率调参而非取固定大值——固定过大等于长期为大概率被丢弃的候选预留显存与算力。</p>\n<p>量化账同样分两本：草稿与目标模型的精度需分别评估。草稿模型量化到 NVFP4/FP8 能减小权重带宽与显存占用，直接压低草稿段延迟；但量化误差会改变 $q$ 的分布形状，拉低 $\\min(1,p/q)$，接受率下降。目标模型量化改变 $p$，同样影响接受率与正确性保证的前提。两者要联合评估，不能只优化草稿侧。</p>\n\n<h3 id=\"alg-speculative-decoding-code-sec-18\">十八 · 失败模式的公式读法</h3>\n<p>三种失败模式都能在第一、二节的公式里找到位置。tokenizer 或分布不一致：$q$ 与 $p$ 错位使 $\\min(1,p/q)$ 在多数位置取小值，连乘迅速衰减，$\\mathbb{E}[\\text{accept}]$ 掉到 1 附近，而分母 $c\\gamma+1$ 不变，加速比跌破 1，时延反而高于朴素解码。$\\gamma$ 固定过大：分母的 $c\\gamma$ 线性抬升，长上下文下验证前向的 KV 与算力被占满，吞吐下降；此时应下调 $\\gamma$ 而不是加大。KV 未正确丢弃：这不是公式能表达的，它破坏的是下一轮的前缀正确性，表现为输出重复或乱序——属于实现缺陷而非算法缺陷，但后果比性能损失更严重。</p>\n<p>工程判断落在一个闭环上：按任务分桶统计实测接受率，用它反推 $\\mathbb{E}[\\text{accept}]$，与验证前向实测耗时构成的 $c\\gamma+1$ 比较，动态调 $\\gamma$；同时把 KV 裁剪长度绑定到接受长度而非验证输入长度，并在残差分布零质量时回退到目标分布采样。这三条构成投机解码在 Blackwell 上稳定运行的最小控制面，其余优化（草稿模型选型、量化配方、部署拓扑）都在此闭环内迭代。</p>\n\n<h3 id=\"alg-speculative-decoding-code-sec-19\">十九 · 接受率塌陷与 γ 失配：这套方案的收益边界</h3>\n<p>核心公式里真正决定成败的不是 γ，而是逐位置比值 <span>p_j/q_j</span> 的连乘项。期望接受长度 <span>E[accept]=Σ_{i=1}^{γ+1}Π_{j=1}^{i}min(1,p_j/q_j)</span> 对前缀位置极其敏感：只要前几个位置的比值显著小于 1，后续连乘迅速衰减，γ 再大也填不满。工程上必须把“每轮实际推进 token 数”作为一等指标采集，而不是只看总吞吐。当草稿与目标 tokenizer 不一致（例如空白、缩进、BPE 合并规则差异），同一前缀下 q 与 p 在词表层面就不可比，接受率骤降，此时验证前向的算力与 KV 读取全部变成净损失，首 token 后时延反而高于朴素解码——这是代码补全场景最典型的失效条件。</p>\n<p>系统代价随 γ 线性增长的部分必须单独核算。目标模型一次并行前向要读入前缀加 γ 个候选的 KV，权重读取带宽被摊薄的前提是这批候选大多被接受；若接受长度只有 1–2，则相当于用 γ 倍的验证算力换 1 个 token。用加速比近似式 <span>speedup≈E[accept]/(c·γ+1)</span> 判断：c 是草稿与目标单步代价之比（草稿小模型 c 远小于 1，但同机部署时显存与算力仍被占用）。当 <span>E[accept] &lt; c·γ+1</span> 时收益转负，此时应收缩 γ 而非继续加长草稿链。长上下文下验证前向的 KV 显存随 γ 增长，与草稿模型权重共同挤压批大小，吞吐被动下降。</p>\n<p>KV 管理的正确性是隐性失效点：拒绝位置及其后的草稿 KV 必须整体丢弃，只保留被接受 token 对应位置；若残留，下一轮前缀与 KV 错位，输出出现重复或乱序，而分布一致性保证也随之失效。伪代码落点应是“接受长度 L → 截断 KV 至 prefix+L → 若 L=γ 追加 bonus token 的 KV”，截断动作与采样动作在同一临界区内完成。调参策略上按任务统计滑动窗口接受率，低于阈值即降 γ 或退回朴素解码；草稿与目标模型需分别做量化评估，任一方的分布偏移都会直接压低 min(1,p/q)。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>观测信号</th><th>工程动作</th></tr></thead><tbody><tr><td>tokenizer/分布不一致</td><td>接受率骤降、时延反超</td><td>统一词表或换草稿选型</td></tr><tr><td>γ 固定过大</td><td>验证 KV 与算力占满</td><td>按接受率动态收缩 γ</td></tr><tr><td>KV 未截断</td><td>重复/乱序输出</td><td>接受长度处强制截断</td></tr></tbody></table>\n<h3 id=\"alg-speculative-decoding-code-sec-20\">二十 · 请求形态的匹配：短前缀、短续写与低延迟 SLO</h3>\n<p>草稿验证的收益结构由「每轮推进的 token 数」与「每轮固定开销」的比值决定。它天然适合的请求形态是<strong>前缀短、续写短、对首 token 后时延敏感</strong>的代码补全：前缀通常只有几十到几百 token，续写目标往往是一行或几行（数十 token 量级），解码步数成为主要成本，而每步只出一个 token 的朴素自回归被权重读取带宽卡死。此时草稿模型用极小代价提出 γ 个候选，目标模型一次前向并行验证，把「γ 次权重读取」压缩成「一次权重读取 + 一次草稿前向」，摊薄了目标模型权重读取带宽。</p>\n<p>反过来，长续写请求（整文件生成、长文档摘要）虽然也能受益，但收益被稀释：每轮验证的固定开销（目标模型一次前向的启动、KV 追加、采样修正）在总时延中占比下降，而 γ 轮次累积的草稿开销上升。真正的分水岭是 SLO 的度量口径——以首 token 后时延（TTFT 之后的每 token 时延）为主时，草稿验证直接压缩解码步数，收益线性可见；以吞吐为主时，草稿模型占用的算力与显存会与批内其他请求争抢 SM 与带宽，收益需要重新核算。</p>\n<p>一个具体的负载画像：单请求前缀约 200 token、续写目标 30 token、SLO 要求首 token 后每 token 时延低于某阈值。朴素解码需 30 次目标前向；若平均接受长度接近 γ，则解码轮次降到个位数，每轮一次目标前向加一次草稿前向。代价是草稿模型常驻显存（即便很小也占一份权重与 KV），以及每轮验证前向的 KV 追加。工程判断：把草稿验证部署在「续写长度 ≤ 数百 token、前缀 ≤ 数千 token」的补全通道上，而不是全站默认开启。</p>\n\n<h3 id=\"alg-speculative-decoding-code-sec-21\">二十一 · 长度分布：γ 与上下文长度的耦合</h3>\n<p>γ 不是越大越好，它与上下文长度存在直接耦合。验证前向要对「前缀 + γ 个候选」做一次并行前向，其 KV 与算力随 γ 线性增长：</p>\n<div class=\"formula\">$$\\text{verify cost} \\approx \\text{base}(L_{\\text{prefix}}) + \\gamma \\cdot \\text{per-token}(L_{\\text{prefix}}+\\gamma)$$</div>\n<p>前缀越长，base 项越大，γ 带来的边际验证开销占比越小，但绝对显存占用越高；前缀短时，γ 的线性项主导，γ 过大直接吃满验证前向的 KV 预算。因此在长上下文场景（前缀数万 token）下，固定大 γ 会让验证前向的 KV 与算力被占满，吞吐下降，而接受长度的提升未必抵得过这部分开销。</p>\n<p>长度分布还影响接受率的统计口径。代码补全的续写往往是「模板化、局部可预测」的片段（括号闭合、变量名复用、函数签名延续），草稿模型容易命中；而开放式续写（自然语言解释、自由命名）接受率显著低。按任务统计接受率、按长度分桶调 γ，是负载配方的核心动作：短前缀短续写用较大 γ 冲上限，长前缀或低接受率任务回落到小 γ 甚至关闭。工程上把 γ 做成请求级参数而非全局常量，按 (任务类型, 前缀长度桶, 历史接受率) 三元组查表。</p>\n\n<h3 id=\"alg-speculative-decoding-code-sec-22\">二十二 · 并发与批大小：两份显存共同约束</h3>\n<p>批大小受草稿模型与目标模型显存共同约束。连续批处理下，一个 batch 里同时存在草稿前向与目标验证前向两类工作：草稿前向是 γ 步自回归、每步小算力大带宽；验证前向是一次大前向、算力密集。二者对 SM 的占用形态不同，混批时容易互相拖慢——草稿步被验证前向的长尾阻塞，验证前向又被草稿步的频繁启动打断。</p>\n<p>可行的配方是把草稿前向与验证前向在调度上分层：草稿阶段用小 batch 快速推进（草稿模型小，单步延迟低），验证阶段把同一批请求的候选拼成一次前向。批大小上限由验证前向的 KV 峰值决定：每个请求在验证时要额外持有 γ 个位置的 KV，批内请求数 × γ 直接乘进 KV 预算。显存吃紧时，先降 γ 再降批大小，因为降 γ 同时削减验证算力与 KV，是双杀。</p>\n<p>代价面：草稿模型额外占用一份权重显存与一份草稿 KV；同机部署时它与目标模型争抢 HBM 带宽，分卡部署时引入跨卡通信（草稿 token 概率需传到目标侧做拒绝采样比较），NVLink 上的小消息往返会进入每轮关键路径。工程判断：草稿模型与目标模型同卡时优先保证目标模型的 KV 余量，草稿 KV 用更激进的块管理；分卡时把概率比较与接受判定放在目标侧完成，减少往返次数。</p>\n\n<h3 id=\"alg-speculative-decoding-code-sec-23\">二十三 · 负载不对时的三种崩法</h3>\n<p>负载配方错配时，草稿验证从加速器变成净损失，表现为三种典型失败。</p>\n<ul>\n<li><strong>接受率骤降</strong>：草稿与目标 tokenizer 或分布不一致（例如草稿用不同分词表、或草稿在领域外数据上训练），逐位置接受概率 min(1,p/q) 大幅走低，首次拒绝频繁发生在第 1、2 个位置，本轮实际推进 token 数接近 1，而代价是「一次草稿前向 + 一次验证前向」，时延反而高于朴素解码。</li>\n<li><strong>γ 固定过大</strong>：验证前向的 KV 与算力线性增长，长上下文下显存与算力被验证占满，批内其他请求被挤出，吞吐下降；同时大 γ 下尾部候选几乎必被拒，浪费的验证算力无法回收。</li>\n<li><strong>KV 错位</strong>：拒绝后未正确丢弃被拒位置及其后的草稿 KV，后续轮次的 KV 与 token 序列错位，输出出现重复或乱序——这是正确性事故，而非性能问题，且因为拒绝采样保证分布一致，错位往往在语义层才暴露。</li>\n</ul>\n<p>量化这三种崩法的代价：接受率低时，speedup ≈ E[accept]/(c·γ+1) 中分子趋近 1、分母含 c·γ 的草稿开销，比值小于 1 即净损失；γ 过大时验证 KV 峰值把批大小压到 1，吞吐塌陷；KV 错位则是不可接受的正确性回归，必须靠「只保留被接受位置 KV、拒绝点之后全部截断」的硬规则堵死。</p>\n\n<h3 id=\"alg-speculative-decoding-code-sec-24\">二十四 · 配方表：按负载选参数</h3>\n<p>把上述判断落成一张可执行的配方表，按请求形态分档：</p>\n<table class=\"mini\">\n<thead>\n<tr><th>负载档位</th><th>前缀/续写</th><th>γ 策略</th><th>批大小约束</th><th>主要风险</th></tr>\n</thead>\n<tbody>\n<tr><td>低延迟补全</td><td>短/短</td><td>较大 γ，按接受率动态回落</td><td>草稿 KV + 验证 KV 双预算</td><td>接受率低时净损失</td></tr>\n<tr><td>中等续写</td><td>中/中</td><td>中等 γ，按长度桶调</td><td>验证 KV 峰值主导</td><td>γ 过大吃满算力</td></tr>\n<tr><td>长上下文</td><td>长/短</td><td>小 γ 或关闭</td><td>前缀 KV 已占大头</td><td>验证 KV 线性增长</td></tr>\n<tr><td>开放式生成</td><td>任意/长</td><td>关闭或极小 γ</td><td>—</td><td>接受率低，收益转负</td></tr>\n</tbody>\n</table>\n<p>表中每一档都对应一个可观测指标：接受长度均值、每轮验证前向的 KV 峰值、批内请求数与 γ 的乘积。运维上把「接受长度均值 / γ」作为健康度指标，低于阈值即自动降 γ；把「验证 KV 峰值 / 总 KV 预算」作为容量水位，超过即降批大小。这两个指标把负载配方从静态配置变成闭环控制。</p>\n<p>一个具体例子：补全通道上某类请求的前缀 200 token、续写 30 token，历史接受长度均值接近 γ 上限，则维持较大 γ 并把批大小压到验证 KV 允许的上限；同一集群里开放式生成请求的接受长度均值长期低于阈值，则对该任务类型直接关闭草稿验证，回到朴素解码，避免草稿模型的显存与算力被无效占用。工程判断落在「按任务类型分通道、按接受率闭环调 γ、按验证 KV 水位调批」这三条硬规则上，而不是给全站一个统一 γ。</p>\n\n<h3 id=\"alg-speculative-decoding-code-sec-25\">二十五 · 负载配方：草稿验证只在“短前缀、高一致性、低并发”的窄带上赚钱</h3>\n<p>草稿验证的收益不是无条件成立的，它被一条极窄的负载带约束住。把期望接受长度写成逐位置概率比的连乘，收益边界就一目了然：</p>\n<div class=\"formula\">$$\\mathbb{E}[\\text{tokens/round}]=\\sum_{i=1}^{\\gamma+1}\\prod_{j=1}^{i}\\min\\left(1,\\frac{p_j}{q_j}\\right),\\quad \\text{speedup}\\approx\\frac{\\mathbb{E}[\\text{accept}]}{c\\cdot\\gamma+1}$$</div>\n<p>分母里的 $c$ 是草稿模型单步成本相对目标模型单步成本的折算系数。这个式子说明两件事：加速比随 $\\gamma$ 增大先升后降，因为分子（接受长度）随 $\\gamma$ 增长趋于饱和，分母却线性膨胀；而分子的每一层连乘都被最弱的那个位置卡住，只要前缀中段出现一次 $p_j/q_j$ 明显小于 1 的位置，后面所有候选的贡献都被乘穿。因此负载配方的核心不是“调大 $\\gamma$”，而是让请求形态落在连乘项普遍接近 1 的区间里。</p>\n<p>适合的请求形态是低延迟代码补全：前缀短、续写短、SLO 以首 token 后时延与每 token 时延为主。短前缀意味着草稿模型自回归 $\\gamma$ 步的串行开销被压在很小的绝对时间上，短续写意味着单轮验证前向的 KV 增长有限；而代码补全的局部确定性（缩进、括号闭合、已声明标识符的复用）让 $p$ 与 $q$ 在同一位置上高度重合，连乘项接近 1，接受长度接近 $\\gamma$。反过来，长上下文摘要、开放式对话、跨语言改写这类请求，续写位置的分布方差大，草稿模型与目标模型的偏好分叉，连乘项迅速衰减，$\\mathbb{E}[\\text{accept}]$ 掉到 1 附近，此时分子约等于 1 而分母是 $c\\cdot\\gamma+1$，加速比直接小于 1——验证前向变成净损失，时延反而高于朴素逐 token 解码。</p>\n<p>并发与批大小是第二个约束面。批大小受草稿模型与目标模型显存共同约束：两个模型同机部署时，草稿模型的权重与它自己的 KV 一起挤占目标模型可用的显存，能开的并发批被压低；分卡部署则把草稿模型的串行 $\\gamma$ 步变成跨卡往返，通信延迟进入每 token 时延的关键路径。更隐蔽的是验证前向的 KV 与算力随 $\\gamma$ 线性增长：批内每个请求都要为 $\\gamma$ 个候选位置预留验证 KV，长上下文下这部分显存与算力被验证占满，有效批大小进一步缩水，吞吐不升反降。所以负载配方里 $\\gamma$ 必须按任务实测接受率动态调，而不是全局固定一个大值。</p>\n<table class=\"mini\"><thead><tr><th>负载特征</th><th>接受长度走向</th><th>系统代价落点</th></tr></thead><tbody><tr><td>短前缀、短续写、代码补全</td><td>连乘项接近 1，接近 $\\gamma$</td><td>解码步数成倍下降，权重读取带宽被摊薄</td></tr><tr><td>长上下文、开放式生成</td><td>连乘项衰减，趋近 1</td><td>验证 KV 与算力线性膨胀，时延转负</td></tr><tr><td>高并发、同机双模型</td><td>不变，但批被显存压小</td><td>草稿权重挤占目标模型显存，吞吐受限</td></tr></tbody></table>\n<p>失效条件里最致命的一条是草稿与目标模型的 tokenizer 或分布不一致：一旦词表切分不同，$q$ 与 $p$ 根本不在同一 token 空间上比较，接受率骤降，连乘项被系统性压到很低，验证前向的开销全额付出却换不回推进长度。另一条是 KV 管理错误——拒绝后未正确丢弃被拒位置及其后的草稿 KV，后续轮次的 KV 与 token 错位，输出出现重复或乱序，这类错误在长会话里会累积放大。工程判断是：先按任务统计接受率分布，把 $\\gamma$ 设在接受长度饱和点之前；再把草稿模型与目标模型的 tokenizer 一致性作为上线前的硬门槛；最后用验证 KV 的显存占用反推批大小上限，而不是先定批再算显存。</p>\n<h3 id=\"alg-speculative-decoding-code-sec-26\">二十六 · 硬件档位：按验证前向的形态选卡，而不是按草稿模型</h3>\n<p>草稿验证的部署决策起点不是“草稿模型多小”，而是“目标模型的一次并行验证前向有多重”。验证前向把 $\\gamma+1$ 个位置塞进同一批，序列维被拉长，注意力计算与 KV 写入按 $\\gamma$ 线性放大，而权重读取量不变——这正是投机解码摊薄带宽的物理来源。因此硬件档位的第一判据是目标模型在该卡上的<b>单次前向时延与 KV 带宽余量</b>，草稿模型只是附带的常驻开销。</p>\n<p>在 Blackwell 上，档位大致分三层。单卡档（B200/B300 单 GPU）：目标模型需在单卡显存内放下权重加一段 KV，草稿模型与目标模型同卡常驻，靠 NVFP4/FP8 权重压缩腾出草稿的显存份额；此时验证前向的算力占用是主要矛盾，$\\gamma$ 稍大就会把单卡的算力预算吃满。双卡档（2-SM MMA 与 tcgen05 的用武之地）：目标模型切两张卡做张量并行，验证前向的集合通信落在 NVLink 5 域内，草稿模型可独立放第三张卡或与其中一张共置。机架档（GB200/GB300 NVL72）：目标模型跨多卡甚至多节点，草稿模型单独成组，验证前向的激活与 KV 通过 NVLink 域广播，此时通信时延而非算力成为验证步的成本主项。</p>\n<p>选档的量化判据可以写成一条粗略的预算不等式：设目标模型单次前向的权重读取时间为 $t_w$、$\\gamma$ 个位置的注意力与 MLP 计算时间为 $t_c(\\gamma)$、跨卡通信时间为 $t_{comm}$，则一轮验证的墙钟时间约为 $\\max(t_w, t_c(\\gamma)) + t_{comm}$。当 $t_c(\\gamma)$ 逼近 $t_w$ 时，继续加大 $\\gamma$ 只增加验证成本而不缩短单轮时间，这就是档位与 $\\gamma$ 的耦合点。工程上先测这条曲线的拐点，再定卡数，而不是先买卡再调 $\\gamma$。</p>\n\n<h3 id=\"alg-speculative-decoding-code-sec-27\">二十七 · 并行拓扑：草稿与目标的放置决定通信账</h3>\n<p>草稿模型与目标模型的放置有三种可行拓扑，各自的代价结构完全不同。</p>\n<ul>\n<li><b>同卡共置</b>：草稿与目标共享一张 GPU 的显存与 SM。优点是零通信、草稿生成与验证切换无跨设备同步；代价是显存被两者共同挤压，KV 预算变小，且草稿自回归的 $\\gamma$ 步与目标验证前向争抢同一批 SM，低接受率时草稿的算力开销直接体现为时延。适合草稿极小（轻量层数、窄隐藏维）且 $\\gamma$ 不大的场景。</li>\n<li><b>分卡同机</b>：草稿独占一张卡，目标模型按张量并行铺在其余卡上。草稿生成与目标验证可以流水重叠——第 $k$ 轮验证进行时，草稿已可基于“乐观前缀”预生成第 $k+1$ 轮候选，但乐观前缀一旦被拒就需要回滚重算，这条流水线的收益完全取决于接受率。跨卡只传 $\\gamma$ 个 token 的 id 与概率，通信量极小，瓶颈在同步点而非带宽。</li>\n<li><b>分离式跨节点</b>：草稿组与目标组分处不同节点，走 NIXL 一类点对点传输。候选 token 与概率的传输量是字节级，但往返时延进入关键路径，只有在目标模型大到必须跨节点、且草稿接受率足够高使每轮推进 token 数可观时才划算。</li>\n</ul>\n<p>拓扑选择的一条硬约束是<b>草稿与目标的 tokenizer 与词表必须逐位一致</b>。分卡部署时这一点容易被忽视：两侧加载了不同版本的 tokenizer 配置，候选 token 的 id 在目标侧被映射到另一个词，接受率骤降且拒绝采样仍在“正确”运行，故障表现为时延而非报错。部署配方里应把 tokenizer 一致性做成启动期断言，而非运行期观察。</p>\n<p>另一个易错点是验证前向的并行维度。目标模型做张量并行时，$\\gamma+1$ 个位置的验证在同一批内完成，各卡拿到的输入序列相同，输出 logits 在词表维切分后需 all-gather 才能做逐位置比较。这一步的通信量与 $\\gamma \\times$ 词表大小成正比，$\\gamma$ 大、词表大时不可忽略，应在拓扑设计时就计入验证步的通信预算。</p>\n\n<h3 id=\"alg-speculative-decoding-code-sec-28\">二十八 · 量化方案：草稿与目标分开评估，拒绝采样的数值敏感点</h3>\n<p>量化在草稿验证里不是单一决策，而是两条独立曲线。目标模型的量化决定验证概率 $p$ 的保真度，草稿模型的量化决定提议概率 $q$ 的保真度，而接受判据 $\\min(1,p/q)$ 与残差分布 $\\max(0,p-q)$ 都直接吃这两个概率的比值。比值对两侧量化误差的敏感度不对称：若 $q$ 被量化得系统性偏高，接受率被压低；若 $p$ 被量化得偏低，残差分布的形状被扭曲，修正 token 的分布偏离目标模型，正确性保证在数值层面被削弱。</p>\n<p>Blackwell 的 NVFP4 与 FP8 给出一条分层路径：目标模型用 FP8 权重加高精度激活，保住 $p$ 的相对排序；草稿模型可以更激进地压到 NVFP4，因为 $q$ 只需近似即可，接受判据本身会修正偏差——但前提是 $q$ 不能出现系统性偏移。工程上应分别对两侧做<b>分布一致性抽检</b>：固定前缀，比较量化前后同一位置的 top-k 概率排序与比值，而不是只看困惑度。困惑度对接受率不敏感，是错的验收指标。</p>\n<p>数值上还有一个必须显式处理的点：拒绝采样要求 $q&gt;0$ 处才有定义，$\\min(1,p/q)$ 在 $q$ 极小时会放大浮点误差。量化后 $q$ 出现零值或次正规数时，接受判据需要钳位处理，否则会出现“本应接受却被判拒”的假拒绝，接受率无故下降且难以归因。这类钳位应写进 kernel 而非框架层，避免每轮多做一次全序列判断。</p>\n<div class=\"formula\">$$\\text{accept}_j=\\min\\left(1,\\frac{p_j}{q_j}\\right),\\qquad \\text{residual}\\propto\\max(0,\\,p_j-q_j)$$</div>\n<p>代价侧：目标模型量化到 FP8 使权重读取字节减半，直接缩短 $t_w$，是投机解码摊薄带宽收益的放大器；草稿模型量化到 NVFP4 使其常驻显存下降，为 KV 腾出空间。两者叠加的显存收益应换算成“可支撑的批大小与上下文长度”，而不是停留在“省了多少 GB”的描述上。</p>\n\n<h3 id=\"alg-speculative-decoding-code-sec-29\">二十九 · KV 策略：只留被接受位置，拒绝即截断</h3>\n<p>草稿验证的 KV 管理与常规解码的根本差别在于<b>写入是投机性的</b>。验证前向会为 $\\gamma+1$ 个位置全部算出 KV，但只有前 $n$ 个被接受的 token（$n$ 为接受长度，全部接受时再加一个 bonus token）对应的 KV 是有效的。被拒位置及其后的草稿 KV 必须丢弃，且丢弃必须发生在下一轮开始之前，否则后续轮次的 KV 与 token 序列错位，输出出现重复或乱序——这是本机制最典型的静默故障。</p>\n<p>实现上有两条路线。其一，验证前向把 KV 写进一块临时缓冲，接受长度确定后再把前 $n$ 个位置的 KV 追加进主 KV 缓存，临时缓冲复用。代价是多一次 KV 拷贝，拷贝量与 $n \\times$ 层数 $\\times$ 头数 $\\times$ 头维成正比，长上下文下这笔拷贝不可忽视。其二，直接写进主缓存但维护一个逻辑长度指针，接受长度确定后把指针回退到 $n$，被拒位置的槽位标记为可覆盖。后者省掉拷贝，但要求分页块管理能正确处理“已写未提交”的块状态，且回退后的槽位在下轮被覆盖前不得被前缀缓存复用逻辑误认。</p>\n<p>显存账要按最坏情况算：验证前向的峰值 KV 需求是 $\\gamma+1$ 个位置，而稳态有效 KV 只增长 $n$ 个位置。$\\gamma$ 大、接受率低时，临时 KV 的峰值占用与有效占用之间的差额就是纯浪费，且这部分浪费随上下文长度线性放大。因此 KV 策略与 $\\gamma$ 必须联合调参：上下文越长，越应压低 $\\gamma$ 或改用临时缓冲加拷贝以换取更小的峰值占用。</p>\n<p>与分页 KV 块管理的接口要明确一条契约：<b>块分配以验证前向的 $\\gamma+1$ 个位置为单位预留，提交以接受长度为单位回收</b>。这条契约把“投机写入”与“分页复用”解耦，避免前缀缓存把未提交的投机 KV 当作有效前缀命中。</p>\n\n<h3 id=\"alg-speculative-decoding-code-sec-30\">三十 · 调度参数：$\\gamma$ 是运行期变量，不是编译期常量</h3>\n<p>调度层的核心参数是 $\\gamma$、批大小与接受率统计窗口。$\\gamma$ 固定过大是本机制最常见的性能反演原因：验证前向的 KV 与算力随 $\\gamma$ 线性增长，而期望推进 token 数的增长是次线性的——由 $\\mathbb{E}[\\text{tokens/round}]=\\sum_{i=1}^{\\gamma+1}\\prod_{j=1}^{i}\\min(1,p_j/q_j)$ 可见，接受率低于 1 时乘积逐项衰减，$\\gamma$ 超过某个点后每轮多验证的位置几乎全部被拒，纯增成本。</p>\n<div class=\"formula\">$$\\text{speedup}\\approx\\frac{\\mathbb{E}[\\text{accept}]}{c\\cdot\\gamma+1}$$</div>\n<p>式中 $c$ 是草稿生成一个 token 相对目标验证一个位置的相对成本。这条式子给出调度器的决策规则：按滑动窗口统计近期接受率 $\\hat{a}$，令 $\\gamma$ 随 $\\hat{a}$ 单调调整，$\\hat{a}$ 高时放大 $\\gamma$ 吃满验证前向的并行度，$\\hat{a}$ 低时收缩到小值甚至退化为 $\\gamma=1$ 以止损。窗口长度要覆盖请求形态的变化周期：代码补全的接受率在同一文件内相对稳定，跨文件切换时跳变，窗口过短会导致 $\\gamma$ 抖动，过长则反应迟钝。</p>\n<p>批大小受两侧显存共同约束，且与 $\\gamma$ 争夺同一份 KV 预算。低延迟代码补全的 SLO 以首 token 后时延与每 token 时延为主，批大小应压到刚好填满验证前向的算力空隙而不显著抬高单请求时延；连续批处理下，不同请求的 $\\gamma$ 可以不同，但同一批内的验证前向需要统一序列长度，工程上按批内最大 $\\gamma$ 补齐，补齐位置的 KV 同样计入峰值。这条补齐开销在混合长短请求时不可忽略，调度器应倾向于把 $\\gamma$ 相近的请求聚成一批。</p>\n<p>一个可复现的配置思路：先用目标模型单卡测出 $t_w$ 与 $t_c(\\gamma)$ 曲线定拐点；按拐点选 $\\gamma$ 上限；草稿模型压到 NVFP4 并做分布一致性抽检；KV 走临时缓冲加提交式回收；调度器以接受率滑动窗口驱动 $\\gamma$，并把 tokenizer 一致性做成启动断言。这套顺序把显存、算力、通信三笔账分开结清，任何一步的实测偏离都能定位到具体环节，而不是笼统地归因于“投机不划算”。</p>\n\n<h3 id=\"alg-speculative-decoding-code-sec-31\">三十一 · 配方边界：从硬件档位到失效条件的联调</h3>\n<p>硬件档位决定草稿与目标模型的放置方式：同卡部署省去一次跨卡往返，但草稿权重与激活直接挤压目标模型的 KV 空间；分卡部署把草稿放到低算力档位，代价是每轮多一次跨卡概率回传与同步，在低延迟代码补全的 SLO 下这段通信落在关键路径上。并行拓扑上，目标模型验证前向是单次并行前向，TP 组越大单步时延越低但每轮同步开销越重；草稿模型自回归 γ 步，天然适合小 TP 或 DP 复制，把草稿的串行步与目标模型的并行验证解耦到不同并行组，是这套配方里最容易被忽略的一刀。</p>\n<div class=\"formula\">$$\\text{round latency}\\approx \\gamma\\cdot t_{\\text{draft}}+t_{\\text{verify}}(\\gamma)+t_{\\text{comm}},\\quad \\text{goodput}\\approx\\frac{\\mathbb{E}[\\text{accept}]}{\\gamma\\cdot t_{\\text{draft}}+t_{\\text{verify}}(\\gamma)+t_{\\text{comm}}}$$</div>\n<p>量化方案必须分开评估：目标模型走 FP8 或 NVFP4 影响验证概率 p 的数值稳定性，草稿模型走更低精度则直接改变 q，两者精度不匹配会系统性拉低 min(1,p/q)。KV 策略只保留被接受位置，被拒位置及其后的草稿 KV 必须显式丢弃，否则下一轮前缀与 KV 错位，输出重复或乱序——这是配方里唯一会静默出错的环节，需在每轮接受长度回写时做断言。调度参数上，γ 不能固定：按任务滑动统计接受率，接受率跌破阈值就缩 γ，把验证前向的 KV 与算力从线性增长里收回来。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>系统代价</th><th>配方动作</th></tr></thead><tbody><tr><td>tokenizer 或分布不一致</td><td>接受率骤降，验证成净损失，时延高于朴素解码</td><td>草稿与目标同源选型，上线前测接受率</td></tr><tr><td>γ 固定过大</td><td>验证 KV 与算力线性涨，长上下文挤占显存</td><td>按接受率动态缩 γ</td></tr><tr><td>被拒 KV 未丢弃</td><td>KV 与 token 错位，输出重复乱序</td><td>接受长度回写加断言</td></tr></tbody></table>\n<p>可复现的配置思路是：先固定目标模型精度与 TP 拓扑，测出单步验证时延随 γ 的曲线；再把草稿模型放到独立并行组，用真实补全流量统计分任务接受率；最后以 goodput 为目标函数扫 γ 与批大小，批大小受两侧显存共同约束而非单侧。边界很清楚——接受率高时这套配方成倍摊薄目标模型权重读取带宽，接受率低或 γ 越过拐点时收益转负，此时正确动作是退回朴素解码而不是继续加 γ。</p>\n<h3 id=\"alg-speculative-decoding-code-sec-32\">三十二 · 验证前向的显存账：γ 把 KV 与激活一起放大</h3>\n<p>投机解码在显存上不是“多一个草稿模型”这么简单，验证前向本身就是一个长度为 $\\gamma$ 的预填式前向。目标模型对“前缀 + γ 个候选”做一次并行前向，KV 需要为这 $\\gamma$ 个位置全部写入，激活也要按 $\\gamma$ 个 query 位置展开。也就是说，即便最终只接受 $a$ 个 token（$a\\le\\gamma$），显存峰值仍然按 $\\gamma$ 计。这一点与分页 KV 块管理正交：块表能决定被拒绝位置的块如何回收，但回收发生在验证之后，峰值已经发生。</p>\n<p>把每轮显存增量写成可核算的形式：设目标模型每 token 每层 KV 字节为 $s_{kv}$、层数 $L$、批大小 $B$，则验证前向的 KV 写入量为</p>\n<div class=\"formula\">$$M_{verify}=B\\cdot\\gamma\\cdot L\\cdot s_{kv}\\cdot 2$$</div>\n<p>系数 2 对应 K 与 V 两份。这个量随 $\\gamma$ 线性增长，而收益侧的期望推进长度是 $\\mathbb{E}[\\text{accept}]$，并不随 $\\gamma$ 线性增长——接受率在 $\\gamma$ 增大时通常递减，因为越靠后的候选越难被接受。于是存在一个显存拐点：当 $M_{verify}$ 把剩余显存吃到无法维持目标批大小时，系统会先降批，再降 $\\gamma$，吞吐随之掉档。工程上的判断是：先按“目标模型权重 + 草稿模型权重 + 最大批的稳态 KV”算出剩余显存，再反解出可承受的 $\\gamma$ 上限，而不是先定 $\\gamma$ 再看显存。</p>\n<p>具体例子：低延迟代码补全场景前缀短、续写短，稳态 KV 不大，显存主要被两份权重占据；此时 $\\gamma$ 的显存约束来自验证前向的瞬时峰值而非稳态，因此可以把 $\\gamma$ 调得比长上下文场景更激进。反过来，一旦请求前缀变长（例如把整文件作为上下文），稳态 KV 抬升，验证峰值叠加后余量迅速消失，这是规模上去后最先崩的一处。</p>\n\n<h3 id=\"alg-speculative-decoding-code-sec-33\">三十三 · 带宽账：摊薄的是权重读取，不是全部</h3>\n<p>投机解码的收益来源被反复引用为“摊薄目标模型权重读取带宽”。要把这句话算清楚：朴素解码每步读一遍目标模型权重、产出 1 个 token，权重读取字节 $W$ 对应 1 token；投机解码每轮读一遍权重、期望产出 $\\mathbb{E}[\\text{accept}]+1$ 个 token（含 bonus），于是每 token 的权重带宽成本降为 $W/(\\mathbb{E}[\\text{accept}]+1)$。但草稿模型自己也要读权重，且是自回归 $\\gamma$ 步、每步读一遍草稿权重 $W_d$。所以每轮的总权重读取是</p>\n<div class=\"formula\">$$W_{round}=W+\\gamma\\cdot W_d,\\quad \\text{每 token 权重成本}=\\frac{W+\\gamma W_d}{\\mathbb{E}[\\text{accept}]+1}$$</div>\n<p>这个式子给出两个直接结论。其一，草稿模型必须显著小于目标模型，否则 $\\gamma W_d$ 会把摊薄效应吃掉；其二，$\\gamma$ 增大时分子线性涨、分母次线性涨，存在最优 $\\gamma$。前文已给出加速比近似 $\\mathbb{E}[\\text{accept}]/(c\\gamma+1)$，其中 $c$ 正是草稿每步相对目标一步的代价系数，与这里的 $W_d/W$ 同源。</p>\n<p>更细的一层是：验证前向虽然一次并行，但它读的是“前缀 + γ”的 KV，KV 读取量也随 $\\gamma$ 增长。在长上下文、大 batch 下，KV 带宽而非权重带宽会成为主导项，此时摊薄权重的收益被 KV 读取抵消。这就是为什么该机制在“前缀短、续写短”的代码补全里收益最干净，而在长上下文对话里收益被稀释。工程判断：按 $W$ 与 KV 读取量的比值决定是否值得上投机，比值低（KV 主导）时应优先做 KV 压缩与分页，而不是加 $\\gamma$。</p>\n\n<h3 id=\"alg-speculative-decoding-code-sec-34\">三十四 · 通信与部署拓扑：同机、分卡、还是分离</h3>\n<p>草稿模型与目标模型同机部署时，两者共享同一份显存池与同一条 HBM 带宽，草稿的 $\\gamma$ 步自回归会与目标模型的验证前向争抢带宽；分卡部署则把带宽压力拆开，但每轮要把草稿产出的 $\\gamma$ 个 token 及其概率 $q$、以及前缀状态传给目标卡，验证完再把接受结果传回。跨卡这一步的通信量不大（token id 与概率是极小载荷），但它是每轮一次的小消息同步，延迟由链路往返决定，在 NVLink 5 域内可接受，跨节点则要谨慎。</p>\n<p>规模上去后先崩的往往不是算力而是拓扑。批大小受草稿与目标模型显存共同约束：同机部署时两者共享池，批一大就互相挤；分卡部署时草稿卡成为独立瓶颈——草稿是自回归 $\\gamma$ 步，串行延迟固定，批一大草稿卡的算力先饱和，目标卡反而空闲，形成流水线里的短板。此时提高批不会提高吞吐，只会拉长每轮时延。判断依据是看草稿卡与目标卡的利用率差：差值扩大即说明草稿侧已成瓶颈，应换更小或更快的草稿模型，而不是继续加批。</p>\n<p>分离式预填/解码架构下还有第三种形态：草稿与验证都放在解码侧，预填侧只负责前缀。这种形态下每轮的小消息同步落在解码实例内部，通信代价可控；但若把草稿放到远端，每轮往返的固定延迟会直接叠加到每 token 时延上，低延迟 SLO 下不可接受。结论是草稿必须与验证同域，跨域只允许出现在批处理型、对尾延迟不敏感的负载里。</p>\n\n<h3 id=\"alg-speculative-decoding-code-sec-35\">三十五 · 功耗与热：γ 步自回归是持续的带宽负载</h3>\n<p>功耗上要区分两种负载形态。目标模型的验证前向是一次大而短的突发：$\\gamma$ 个位置并行，算力利用率高、持续时间短；草稿模型的 $\\gamma$ 步自回归是一串小而长的连续负载：每步只处理 1 个 token、批内并行度低、几乎全程卡在权重读取上，HBM 带宽持续占用而 SM 利用率低。后者在整机功耗曲线上表现为一段平坦的高带宽平台，而不是尖峰。对 NVL72 这种整柜部署，草稿侧的持续带宽负载会抬高整柜的稳态功耗，压缩可用的功耗余量，进而限制可维持的批大小。</p>\n<p>这与“接受率低时验证开销反成净损失”是同一件事的两个面：接受率低意味着每轮推进的 token 少，草稿的 $\\gamma$ 步自回归被摊到更少的有效 token 上，单位有效 token 的能耗上升。工程上应统计每任务的接受率并动态调 $\\gamma$——接受率高时放大 $\\gamma$ 摊薄权重读取，接受率低时收缩 $\\gamma$ 减少无效草稿步。固定 $\\gamma$ 在混合负载下必然在某一侧浪费：对高接受率请求太小、对低接受率请求太大。</p>\n<p>具体例子：同一台机器上混跑代码补全（高接受率）与开放式对话（低接受率），若用同一 $\\gamma$，对话请求每轮大量草稿被拒，草稿步的功耗全成沉没成本，且这些被拒位置的 KV 还要写入再丢弃，等于白烧带宽。按请求类型分路由、分 $\\gamma$，比全局调参更有效。</p>\n\n<h3 id=\"alg-speculative-decoding-code-sec-36\">三十六 · 尾延迟：拒绝路径才是长尾来源</h3>\n<p>平均时延好看不代表 SLO 达标。投机解码的时延分布是双峰的：全部接受时一轮推进 $\\gamma+1$ 个 token，极快；首次拒绝发生在第 1 个位置时，一轮只推进 1 个 token，却付出了草稿 $\\gamma$ 步加一次验证前向的全部代价，比朴素解码还慢。尾延迟就来自后者。设首次拒绝位置为 $k$，则该轮有效推进 $k$ 个 token、代价为 $\\gamma$ 步草稿加一次验证，单位 token 代价为 $(\\gamma c+1)/k$，$k=1$ 时最坏。</p>\n<p>控制尾延迟的手段有三条，都是机制层的：其一，按任务统计接受率分布而非均值，对接受率方差大的负载用较小 $\\gamma$，牺牲上限换尾部；其二，在草稿侧做早停——当草稿模型对某位置的置信度低于阈值时提前终止提案，用更短的 $\\gamma$ 换更确定的接受，避免“提了 γ 个只中 1 个”；其三，把 bonus token 的采样与下一轮草稿启动重叠，隐藏轮间气泡。第三条依赖 KV 只保留被接受位置这一前提：被拒位置及其后的草稿 KV 必须正确丢弃，否则下一轮 KV 与 token 错位，输出出现重复或乱序——这类错误在尾延迟统计里表现为偶发的超长轮次，实为正确性缺陷而非性能问题。</p>\n<p>还有一处常被忽略的尾延迟源：草稿与目标 tokenizer 或分布不一致时接受率骤降，验证前向开销变成净损失，时延反而高于朴素解码。这类失败不是渐变而是断崖，监控上应把“每轮接受长度”作为一等指标，其分布左移即为分布漂移的早期信号。</p>\n\n<h3 id=\"alg-speculative-decoding-code-sec-37\">三十七 · 规模上去以后哪里先崩：一条判定顺序</h3>\n<p>把上述各项按“先崩顺序”排成工程判定链，比逐项调参更有效。第一崩通常是显存峰值：验证前向按 $\\gamma$ 计 KV 与激活，稳态 KV 一长，余量先没，表现为批大小被迫下调。第二崩是草稿侧算力：批一大，草稿的 $\\gamma$ 步串行自回归先饱和，目标卡空闲，吞吐不再随批增长。第三崩是 KV 带宽：长上下文下验证前向读 KV 的量超过权重读取，摊薄权重的收益被抵消。第四崩才是通信：跨域小消息往返把每 token 时延抬过 SLO。功耗与热通常最后体现，但它会反过来压缩前三项的可用余量。</p>\n<p>对应的容量规划做法是：先用目标模型权重加草稿权重加最大批稳态 KV 定显存上限，反解 $\\gamma$ 与批的可行域；再用草稿侧算力定批的上界；然后用 $W$ 与 KV 读取量之比判断投机是否值得；最后用接受长度分布定 $\\gamma$ 的动态范围。四步里任何一步不满足，就退回朴素解码或改用多解码头这类不引入第二模型的方案——那条路不依赖两模型分布一致性，部署复杂度低，代价是草稿质量受目标模型隐状态约束。</p>\n<p>一个可落地的运行时策略：以每轮接受长度 $a$ 为反馈量，维护 $\\gamma$ 的自适应控制器，目标是把 $(\\gamma c+1)/(a+1)$ 压在阈值以下；当 $a$ 的滑动分位数跌破阈值时收缩 $\\gamma$，当 $a$ 稳定在高位时缓慢放大 $\\gamma$ 并观察显存峰值是否触顶。控制器只看两个量——接受长度分位数与验证前向的显存峰值——就能同时守住吞吐与尾延迟，不需要对每个任务手工调参。</p>\n\n<h3 id=\"alg-speculative-decoding-code-sec-38\">三十八 · 规模上去以后，先崩的是验证前向的 KV 与带宽账</h3>\n<p>把草稿验证放进真实服务后，系统代价的重心并不在草稿模型本身，而在目标模型那次并行验证前向。设草稿长度 γ、目标模型每步权重读取字节为 W、每 token KV 字节为 k，则一轮的显存流量近似为 <span class=\"formula\">$$M_{\\text{round}}\\approx W + (\\gamma+1)\\,k\\cdot L$$</span>（L 为层数聚合系数）。γ 每加一，验证前向的 KV 与算力就线性抬一档，而收益上限只由 <span class=\"formula\">$$\\text{speedup}\\approx\\frac{\\mathbb{E}[\\text{accept}]}{c\\cdot\\gamma+1}$$</span> 决定，c 是草稿自回归相对目标单步的成本比。接受率不随 γ 增长时，分母先吃掉分子，收益转负。代码补全场景前缀短、续写短，W 的摊薄效果明显；一旦上下文拉长，k 项压过 W，验证前向从“摊薄带宽”变成“额外带宽”。</p>\n<p>第二个崩点是显存与批大小的耦合。草稿模型与目标模型同机部署时，草稿权重、目标权重、两套 KV 池共享同一张卡的容量，批大小被两者共同约束；分卡部署则把约束转成通信——每轮草稿产出 γ 个候选 token 及其概率 q，必须传到目标卡，验证后的接受掩码与残差采样结果再传回，跨卡往返落在每轮的关键路径上。NVLink 域内这段开销尚可摊薄，跨节点走 NIXL/NCCL 时，γ 越大单轮传输的 token 与概率张量越大，尾延迟被通信拉长。低延迟 SLO 下尾延迟比均值更要命：一轮被拒后丢弃被拒位置及其后的草稿 KV，下一轮从更短前缀重跑，长尾请求的轮次方差直接放大 p99。</p>\n<p>功耗与失效条件要一起看。草稿自回归是逐 token 的小前向，算力利用率低但持续占卡；目标验证前向是大矩阵乘，功耗尖峰集中在每轮一次。γ 固定过大时，验证前向把 KV 与算力占满，吞吐下降而单请求时延未必改善。真正需要动态调的是 γ：按任务统计接受率，接受率高时放大 γ 摊薄 W，接受率低时缩到 1–2 避免净损失。最隐蔽的失败模式是草稿与目标 tokenizer 或分布不一致，接受率骤降，验证开销变成纯损失，时延反高于朴素解码；其次是拒绝后未正确丢弃草稿 KV，后续轮次 KV 与 token 错位，输出重复或乱序。工程判断：先测接受率分布再定 γ，把草稿 KV 与目标 KV 分开记账，尾延迟按轮次方差而非均值做容量规划。</p>\n<h3 id=\"alg-speculative-decoding-code-sec-39\">三十九 · 精度失败模式：接受率骤降与分布错位</h3>\n<p>投机解码的收益完全建立在接受率之上，而接受率是草稿分布 $q$ 与目标分布 $p$ 一致性的函数。一旦两模型在 tokenizer、词表映射或数值精度上出现错位，$\\min(1,p/q)$ 会系统性地偏向拒绝，验证前向从\"摊薄带宽\"变成\"纯开销\"。最典型的精度失败是 tokenizer 不一致：草稿模型用一套 BPE 切分，目标模型用另一套，同一前缀在两边被切成不同 token 序列，草稿提出的候选在目标模型词表里根本对不上位置，逐位置比较退化为随机拒绝。这类问题不会报错，只会让接受率静默下滑，监控上表现为接受长度分布整体左移。</p>\n<p>第二类是量化引入的分布偏移。草稿与目标分别量化时，草稿的 NVFP4/FP8 舍入误差会放大 $q$ 与 $p$ 的 KL 距离，尤其在低概率尾部，残差分布 $\\max(0,p-q)$ 归一化后采样出的修正 token 与草稿候选频繁冲突。诊断手段是把每轮的被拒位置索引与对应位置的 $p/q$ 比值打点上报，若拒绝集中在前几个位置且比值长期低于阈值，说明是分布偏移而非任务本身难。工程上应把接受率按任务类型分桶统计，代码补全的标识符续写与自然语言注释的接受率不在同一量级，混在一起的平均值会掩盖局部塌陷。</p>\n<div class=\"formula\">$$\\text{accept rate}=\\frac{1}{N}\\sum_{r=1}^{N}\\frac{L_r}{\\gamma+1},\\quad L_r=\\text{本轮接受长度}$$</div>\n<p>代价上，接受率每下降一档，等价于每 token 的目标模型前向次数上升，直接体现为每 token 时延（TPOT）抬升与目标模型权重读取带宽的重复消耗。具体例子：某代码补全服务在切换草稿模型版本后未重跑 tokenizer 对齐校验，接受长度从接近 $\\gamma$ 的水平跌到个位数，验证前向的 KV 占用不变但有效推进 token 数锐减，尾延迟尖刺随之出现。回滚策略是把草稿模型版本与 tokenizer 哈希绑定为发布单元，接受率跌破基线即自动切回上一版草稿。</p>\n\n<h3 id=\"alg-speculative-decoding-code-sec-40\">四十 · 显存失败模式：γ 过大与 KV 错位导致的 OOM</h3>\n<p>验证前向的 KV 与算力随 $\\gamma$ 线性增长，这是 OOM 的第一来源。草稿模型自身占一份显存，目标模型验证时要把前缀加 $\\gamma$ 个候选拼成一个序列做一次前向，激活与 KV 峰值按 $\\gamma$ 放大。长上下文场景下前缀本身已占大量 KV，再叠加 $\\gamma$ 个候选位置，分页 KV 块的分配请求会在瞬时超过池容量，触发分配失败而非优雅降级。诊断要看验证前向时刻的 KV 块占用曲线与峰值请求量，而不是平均占用。</p>\n<p>第二来源是拒绝后 KV 未正确丢弃。被拒位置及其后的草稿 KV 若残留在块表里，下一轮前缀会带着错位的历史继续推进，表现为输出重复、乱序，同时 KV 池被无效块逐渐蚕食，最终 OOM。这类 bug 的隐蔽性在于它先表现为质量退化，再表现为显存泄漏。监控上应对每轮\"接受长度\"与\"实际释放块数\"做一致性校验：释放块数应等于 $\\gamma+1-L_r$ 对应的位置数，不等即告警。</p>\n<table class=\"mini\"><thead><tr><th>失败现象</th><th>根因</th><th>诊断信号</th><th>处置</th></tr></thead><tbody><tr><td>验证前向 OOM</td><td>$\\gamma$ 固定过大 + 长前缀</td><td>KV 峰值请求超池容量</td><td>按上下文长度动态缩 $\\gamma$</td></tr><tr><td>显存缓慢泄漏</td><td>被拒位置 KV 未释放</td><td>释放块数与接受长度不符</td><td>回滚到块表校验通过的版本</td></tr><tr><td>输出重复乱序</td><td>KV 与 token 错位</td><td>前缀哈希与块表不一致</td><td>丢弃该请求 KV 重算</td></tr></tbody></table>\n<p>代价是显存与吞吐的双向挤压：$\\gamma$ 过大时验证前向把显存与算力占满，批内其他请求的调度空间被压缩，吞吐下降。具体例子：在 NVL72 单机多卡部署中，草稿与目标分卡放置，验证前向的激活峰值落在目标卡上，若 $\\gamma$ 未随上下文自适应，长请求会把目标卡的 KV 池打到上限，短请求被迫排队，形成批抖动。</p>\n\n<h3 id=\"alg-speculative-decoding-code-sec-41\">四十一 · 调度失败模式：批抖动与路由不均</h3>\n<p>连续批处理下，投机解码的每轮推进 token 数是不确定的随机变量，$\\mathbb{E}[\\text{tokens/round}]$ 决定了一轮的实际工作量。当同一批内混有高接受率与低接受率请求时，低接受率请求每轮只推进一两个 token 却占用完整的验证前向槽位，批的有效吞吐被拉低，调度器反复重组批次，形成批抖动。抖动信号是批内请求的完成时间方差与重组频率同时上升。</p>\n<div class=\"formula\">$$\\text{speedup}\\approx\\frac{\\mathbb{E}[\\text{accept}]}{c\\cdot\\gamma+1}$$</div>\n<p>路由不均是分离式部署的特有失败：预填节点与解码节点之间，草稿模型若只部署在部分解码节点，请求按轮询路由会把大量请求打到无草稿的节点上退化为朴素解码，或者把草稿节点压满而其他节点空闲。诊断要看每节点的接受率与每节点验证前向排队时长，两者同时偏离集群均值即路由失衡。工程判断是按接受率而非按连接数做路由权重，把高接受率任务导向草稿齐备的节点。</p>\n<p>代价体现为尾延迟尖刺：批抖动使 P99 时延与 P50 拉开数量级差距，路由不均使部分节点成为长尾。具体例子：代码补全请求前缀短、续写短，本应高接受率，但若路由把大量请求集中到单卡草稿节点，该节点验证前向排队，尾延迟尖刺出现在流量高峰而非单请求本身变慢。处置是给草稿节点设并发上限并对溢出请求做快速降级——直接走目标模型朴素解码，牺牲加速比换稳定时延。</p>\n\n<h3 id=\"alg-speculative-decoding-code-sec-42\">四十二 · 尾延迟尖刺的成因链与监控指标</h3>\n<p>尾延迟尖刺很少是单点故障，而是一条链：接受率下滑 → 每轮有效推进 token 减少 → 批内槽位占用时间变长 → 调度器重组 → 验证前向排队 → P99 抬升。监控必须按这条链布点，而不是只看端到端时延。第一层指标是接受长度分布的分位数，第二层是每轮验证前向的排队时长，第三层是批重组频率与批内完成时间方差，第四层是 KV 池峰值占用与分配失败计数。</p>\n<ul>\n<li>接受率按任务桶统计，跌破基线触发草稿版本回滚。</li>\n<li>验证前向排队时长的 P99 与 P50 比值，超过阈值说明调度或路由失衡。</li>\n<li>KV 释放块数与接受长度的一致性校验，不等即视为 KV 错位 bug。</li>\n<li>批内请求完成时间方差，方差上升先于端到端尾延迟恶化，是早期信号。</li>\n<li>草稿模型与目标模型的 tokenizer 哈希、量化配置哈希随请求打点，便于定位版本错配。</li>\n</ul>\n<p>代价上，监控本身要轻：每轮打点若同步写日志会拖慢解码循环，应做采样与异步聚合，只对拒绝位置索引与 $p/q$ 比值做低开销环形缓冲。具体例子：把每轮的 $\\gamma$、接受长度、被拒首位置、验证前向耗时四项做成定长记录，按请求聚合后上报，既能定位精度问题也能定位调度问题，而不引入额外同步开销。</p>\n\n<h3 id=\"alg-speculative-decoding-code-sec-43\">四十三 · 回滚路径：分级降级与版本绑定</h3>\n<p>回滚不是单一动作，而是分级降级。第一级是参数级：动态缩 $\\gamma$，按上下文长度与实时接受率把 $\\gamma$ 压到保守值，验证前向的 KV 与算力随之回落，代价是加速比下降但时延可控。第二级是路径级：关闭投机，请求直接走目标模型朴素解码，彻底消除草稿显存与验证开销，这是接受率塌陷或草稿节点过载时的兜底。第三级是版本级：把草稿模型、tokenizer、量化配置绑定为一个发布单元，接受率或 KV 一致性校验失败即整体切回上一版。</p>\n<p>分级降级的触发条件必须可观测、可自动执行。参数级触发看接受率滑动窗口跌破阈值；路径级触发看验证前向排队时长或草稿节点并发超限；版本级触发看 KV 释放一致性校验失败或输出质量告警。回滚后要保留失败样本的请求级追踪，否则同一版本会反复被灰度上线又反复回滚。</p>\n<p>代价判断：路径级降级牺牲的是成倍降低解码步数的收益，换来的是时延上界的确定性；版本级回滚牺牲的是新草稿模型的选型收益，换来的是分布一致性的保证。具体例子：当草稿与目标 tokenizer 错配导致接受率骤降时，参数级缩 $\\gamma$ 只能缓解不能根治，必须走版本级回滚，因为错位是发布单元级别的缺陷。工程上应把\"接受率基线 + KV 一致性校验\"作为投机解码服务的发布门禁，任何一项不达标即阻断上线，这比事后诊断便宜得多。</p>\n\n<h3 id=\"alg-speculative-decoding-code-sec-44\">四十四 · 失败模式与诊断：接受率塌陷、验证前向反噬与 KV 错位</h3>\n<p>草稿验证的收益完全建立在接受率之上。公式 <span class=\"formula\">$$\\text{speedup}\\approx\\frac{\\mathbb{E}[\\text{accept}]}{c\\cdot\\gamma+1}$$</span> 里，分母是草稿自回归成本加一次目标验证前向，分子是本轮实际推进的 token 数。一旦草稿与目标模型的 tokenizer 不一致、或两者分布漂移（例如草稿用不同量化精度、目标模型换了 checkpoint 而草稿未同步），<span class=\"formula\">$$\\min(1,p_j/q_j)$$</span> 的逐位置接受概率骤降，<span class=\"formula\">$$\\mathbb{E}[\\text{accept}]$$</span> 逼近 1，分子塌到分母以下，验证前向的开销变成净损失，首 token 后时延反而高于朴素解码。诊断上不要只看端到端延迟，要在每轮记录实际接受长度与 γ 的比值、以及被拒绝位置的 <span class=\"formula\">$$p-q$$</span> 残差质量；接受长度持续低于 γ 的一半就是明确的回滚信号，此时应把 γ 调回小值或直接旁路草稿路径，退回目标模型逐 token 解码，保证 SLO 不被击穿。</p>\n<p>第二类失效是 γ 固定过大。验证前向的 KV 与算力随 γ 线性增长，长上下文代码补全里前缀本就占着显存，γ 个候选位置再叠加一份验证 KV，显存与算力被验证占满，批大小被迫压缩，吞吐下降甚至触发 OOM。监控要盯住每轮验证前向的峰值显存增量与草稿模型常驻显存之和，把“草稿显存 + γ·验证 KV”作为批调度的硬约束，而不是事后救火。γ 应按任务统计的接受率动态调整：接受率高时放大 γ 摊薄权重读取带宽，接受率低时收缩 γ 把算力还给目标模型。</p>\n<p>第三类是最隐蔽的 KV 错位：拒绝后未正确丢弃被拒位置及其后的草稿 KV，后续轮次的前缀 KV 与 token 序列对不上，输出出现重复片段或乱序。这类 bug 不会在单请求短续写上暴露，只在高并发、连续批处理、多轮拼接时才显现，表现为尾延迟尖刺与偶发质量事故。工程上应把“只保留被接受 token 对应位置的 KV、被拒位置及其后全部丢弃、全接受时追加 bonus token”做成不可绕过的路径，并在每轮断言 KV 长度等于已接受 token 数；回滚策略按请求粒度而非全局粒度执行，单请求接受率异常时降级到朴素解码，全局指标恶化时才关闭草稿路径并回退到上一版草稿权重。</p>\n<table class=\"mini\"><thead><tr><th>症状</th><th>根因</th><th>监控指标</th><th>处置</th></tr></thead><tbody><tr><td>时延高于朴素解码</td><td>接受率塌陷</td><td>接受长度/γ、残差质量</td><td>缩 γ 或旁路草稿</td></tr><tr><td>OOM、吞吐下降</td><td>γ 过大、验证 KV 线性增长</td><td>验证峰值显存增量</td><td>按接受率动态调 γ</td></tr><tr><td>重复/乱序输出</td><td>被拒 KV 未丢弃</td><td>KV 长度与接受数一致性</td><td>请求级回滚</td></tr></tbody></table>\n<h3 id=\"alg-speculative-decoding-code-sec-45\">四十五 · 对照轴：把候选算法放到同一张坐标上</h3>\n<p>本片段不再重复拒绝采样的机制推导，只解决一个工程问题：当团队手里同时握着草稿-验证、多解码头投机、特征级投机采样、投机检索预取这几条路线时，凭什么选其中一条，以及选完之后在什么条件下必须换掉它。对照的轴只有三条，且都能在部署前量化：其一，是否引入第二个模型权重（决定显存与部署拓扑）；其二，验证阶段是否需要额外前向（决定每轮固定开销）；其三，接受率由什么决定（决定收益上限与漂移风险）。草稿-验证在这三条轴上的取值是：引入独立草稿模型、需要一次目标模型并行前向、接受率由两模型分布一致性决定。多解码头投机不引入第二个模型，用目标模型隐状态挂轻量头，接受率由头与主干的一致性决定；特征级投机采样在特征层做匹配，验证粒度更细但每轮结构开销不同。把这三条轴画成表，选型就从“感觉哪个快”变成“填三个格子”。</p>\n<table class=\"mini\"><thead><tr><th>算法</th><th>额外权重</th><th>验证前向</th><th>接受率决定因素</th><th>主要代价</th></tr></thead><tbody><tr><td>草稿-验证</td><td>独立草稿模型</td><td>目标模型一次并行前向</td><td>两模型分布/tokenizer 一致性</td><td>草稿显存 + 验证 KV 随 γ 线性增长</td></tr><tr><td>多解码头投机</td><td>轻量头（挂在目标模型上）</td><td>复用目标模型隐状态</td><td>头与主干的训练对齐度</td><td>头训练成本、头容量上限</td></tr><tr><td>特征级投机采样</td><td>视实现而定</td><td>特征层匹配 + 目标验证</td><td>特征空间对齐度</td><td>每轮结构开销、实现复杂度</td></tr><tr><td>投机检索预取</td><td>无生成模型</td><td>不适用（检索命中即用）</td><td>检索命中率</td><td>命中率低时纯属预取浪费</td></tr></tbody></table>\n<p>这张表的用法是排除法而非打分法：先看显存预算能否容纳第二个模型，不能则草稿-验证直接出局；再看任务是否允许训练轻量头，不允许则多解码头出局；剩下的一条若接受率结构性偏低，就该考虑检索预取这类不依赖分布一致性的路线。注意草稿-验证是四条里唯一能给出“输出分布与目标模型严格一致”保证的，这个性质在代码生成与工具调用上是硬需求，其他路线在正确性敏感场景要额外论证。</p>\n\n<h3 id=\"alg-speculative-decoding-code-sec-46\">四十六 · 决策表：按负载形态与 SLO 类型分流</h3>\n<p>选型不能只看算法属性，要把负载形态与 SLO 类型一起放进决策表。草稿-验证的收益公式是 <span class=\"formula\">$$\\text{speedup}\\approx\\frac{\\mathbb{E}[\\text{accept}]}{c\\cdot\\gamma+1}$$</span>，其中 c 是草稿模型单步相对目标模型的成本比。这个式子说明两件事：分母里 γ 是线性项，分子里期望接受长度受 γ 影响但边际递减；因此存在一个最优 γ，超过它加速比回落。决策表的第一列应当是“每轮期望接受长度能否稳定超过 c·γ+1 的盈亏线”，而不是“草稿模型有多小”。</p>\n<table class=\"mini\"><thead><tr><th>负载形态</th><th>SLO 主导项</th><th>推荐路线</th><th>适用条件</th></tr></thead><tbody><tr><td>低延迟代码补全，前缀短续写短</td><td>首 token 后时延、每 token 时延</td><td>草稿-验证</td><td>接受率高且稳定，草稿与目标同机或分卡部署可行</td></tr><tr><td>通用对话，续写长、分布宽</td><td>吞吐为主</td><td>多解码头投机或不用投机</td><td>接受率波动大，草稿-验证的验证开销易成净损失</td></tr><tr><td>工具调用/结构化输出</td><td>正确性 + 时延</td><td>草稿-验证（配文法约束）</td><td>必须保持分布严格一致，接受率受约束解码影响需实测</td></tr><tr><td>检索增强生成，候选高度可预测</td><td>时延</td><td>投机检索预取</td><td>命中率高，不依赖草稿模型</td></tr></tbody></table>\n<p>具体例子：一个代码补全服务，前缀通常只有几十到几百 token，续写以整行或整块为主，草稿模型用同族小模型，接受率天然偏高，此时 γ 取中等值即可让期望接受长度明显超过盈亏线，解码步数成倍下降，摊薄目标模型权重读取带宽——这正是该机制被提出的原始场景。反过来，一个开放式对话服务，续写长、下一 token 分布宽，草稿模型与目标模型的分布一致性差，接受率低，验证前向的固定开销每轮都付，时延反而高于朴素解码，这时决策表应把它推向多解码头或不投机。</p>\n\n<h3 id=\"alg-speculative-decoding-code-sec-47\">四十七 · 适用条件的量化判据</h3>\n<p>把“适用”写成可测判据，避免上线后才发现收益转负。第一条判据是接受率的下界：由加速公式反解，只有当 <span class=\"formula\">$$\\mathbb{E}[\\text{accept}]&gt;c\\cdot\\gamma+1$$</span> 时才有正收益；工程上应先在目标负载上采样统计每轮接受长度分布，而不是用平均值拍板，因为分布长尾会让部分请求的时延劣化。第二条判据是 γ 的稳定性：γ 固定过大使验证前向的 KV 与算力线性增长，长上下文下显存与算力被验证占满，吞吐下降；因此 γ 必须按任务接受率动态调，且要有上限保护。第三条判据是 tokenizer 与分布一致性：草稿模型与目标模型 tokenizer 或分布不一致时接受率骤降，验证前向开销变成净损失，这一条在选型阶段就要用同一批真实请求做对齐检查，不能靠离线基准的通用分数。</p>\n<ul>\n<li>显存判据：草稿模型权重 + 目标模型权重 + 验证阶段 γ 个位置的 KV 必须落在同一批卡的容量内；草稿与目标同机部署省通信，分卡部署省显存但引入跨卡同步。</li>\n<li>时延判据：低延迟 SLO 下，验证前向的一次往返必须短于被它替代的 γ 次朴素解码往返，否则机制本身不成立。</li>\n<li>漂移判据：接受率随请求类型变化，需按任务维度分别统计，单一全局接受率会掩盖某些子集的净损失。</li>\n</ul>\n<p>具体例子：某服务把 γ 固定在一个较大值以追求理论上限，短前缀请求尚可，长上下文请求下验证前向的 KV 与算力线性增长，显存被验证占满，吞吐下降，这正是失败模式里“γ 过大”的典型形态；修法不是换算法，而是把 γ 改为按上下文长度与历史接受率联合调参，并对长上下文请求设更小的 γ 上限。</p>\n\n<h3 id=\"alg-speculative-decoding-code-sec-48\">四十八 · 与多解码头、特征级路线的取舍细节</h3>\n<p>草稿-验证与多解码头投机的核心差别在部署复杂度与选型自由度：草稿-验证依赖独立草稿模型，接受率受两模型分布一致性约束，部署复杂度更高，但草稿可独立选型——可以按任务换一个更小的同族模型，甚至按领域换专用草稿，而不动目标模型。多解码头不引入第二个模型，用目标模型隐状态挂轻量头，显存友好、部署简单，但头的容量与训练对齐度决定接受率上限，且换任务往往要重训头。工程判断是：若团队有能力维护两套权重的版本对齐与量化评估，且任务分布相对集中（代码补全就是典型），草稿-验证的收益上限更高；若运维带宽有限、任务分布宽，多解码头是更稳的默认。特征级投机采样在特征层做匹配，验证粒度更细，但每轮结构开销与实现复杂度更高，适合对接受率有极致要求且愿意承担实现成本的团队。</p>\n<p>还有一条容易被忽略的取舍：草稿-验证的拒绝采样保证输出分布与目标模型严格一致，这是它在正确性敏感场景的护城河；多解码头与特征级路线若未做严格的接受-修正，分布偏差需要单独论证。因此在工具调用、结构化输出这类“错一个 token 就废”的场景，即使接受率略低，草稿-验证仍是首选，代价是部署复杂度。量化方面，草稿与目标模型需分别评估精度，联合量化会同时改变 q 与 p，接受率与正确性保证都要重新验证，不能沿用未量化时的 γ。</p>\n\n<h3 id=\"alg-speculative-decoding-code-sec-49\">四十九 · 切换与退出：什么信号出现时换算法</h3>\n<p>选型不是一次性决定，要定义切换信号。信号一：按任务统计的接受率持续低于盈亏线，且调小 γ 后仍无改善——说明两模型分布一致性是结构性缺陷，应转向多解码头或不投机。信号二：验证前向的 KV 与算力在长上下文下成为瓶颈，显存与算力被验证占满——说明 γ 策略与上下文长度未解耦，先修 γ 调度，修不动再换路线。信号三：出现 KV 与 token 错位导致的重复或乱序输出——这是拒绝后未正确丢弃被拒位置及其后的草稿 KV 所致，属于实现缺陷而非算法缺陷，应先修 KV 管理再谈换算法，否则换任何路线都会带病上线。信号四：草稿模型版本升级或目标模型换量化后接受率骤降，应回滚或重新对齐 tokenizer 与分布，而不是立刻推翻架构。</p>\n<p>退出路径的设计要与容量规划联动：草稿-验证的规模上限受草稿模型显存与验证前向算力约束，当批大小受草稿模型与目标模型显存共同约束时，扩容的边际成本高于纯目标模型部署；因此在大规模容量规划里，应把草稿-验证视为“低延迟档”的专用配置，而不是全局默认。具体例子：一个同时服务代码补全与开放式对话的集群，按请求类型分流——代码补全走草稿-验证的小 γ 配置，对话走多解码头或不投机，两套配置共享目标模型权重但独立管理草稿与 γ，这样既保住了低延迟档的收益，又避免了宽分布请求上的净损失。</p>\n<p>最终落在一条工程判断上：草稿-验证的选型依据不是“草稿模型多小”，而是“每轮期望接受长度能否稳定超过 c·γ+1 的盈亏线，且两模型分布一致性在目标负载上可复现”。把这条判据写进上线检查单，配合按任务维度的接受率监控与 γ 动态上限，机制才从论文里的加速手段变成可运维的低延迟档能力。</p>\n\n<h3 id=\"alg-speculative-decoding-code-sec-50\">五十 · 选型边界：草稿验证何时该让位给多解码头与朴素解码</h3>\n<p>草稿验证与多解码头投机属于同一族但代价结构相反。多解码头不引入第二个模型，在目标模型隐状态上挂轻量头，显存增量小、部署链路短，但草稿分布与目标分布共享同一主干，接受率的调优空间被主干绑定；草稿验证则允许草稿模型独立选型（更小、更专、可单独量化），代价是双模型同机或分卡部署、显存与算力双重占用，且接受率被两模型分布一致性硬约束——tokenizer 不一致或训练语料分布偏移会直接让接受率骤降。选型的判据不是“哪个更快”，而是“接受率能否被稳定观测并反馈到 γ”。用 <span class=\"formula\">$$\\text{speedup}\\approx\\frac{\\mathbb{E}[\\text{accept}]}{c\\cdot\\gamma+1}$$</span> 做粗判：c 为草稿单步相对目标验证前向的代价比，当 E[accept] 接近 γ+1 时收益最大；一旦 E[accept] 跌到 c·γ 量级以下，分母的验证开销吞掉分子，草稿验证就是净损失，此时多解码头或朴素解码更稳。</p>\n<p>决策表按三个可观测维度切分，避免凭感觉调参：</p>\n<table class=\"mini\"><thead><tr><th>条件</th><th>草稿验证</th><th>多解码头</th><th>朴素解码</th></tr></thead><tbody><tr><td>接受率稳定且可在线统计</td><td>首选，γ 动态调</td><td>次选</td><td>否</td></tr><tr><td>草稿与目标 tokenizer/分布一致</td><td>必需前提</td><td>天然满足</td><td>—</td></tr><tr><td>显存余量紧张、单机单卡</td><td>否（双模型挤占）</td><td>首选</td><td>兜底</td></tr><tr><td>长上下文、验证 KV 随 γ 线性涨</td><td>γ 须压小或禁用</td><td>较友好</td><td>兜底</td></tr><tr><td>正确性敏感（代码、工具调用）</td><td>分布严格一致，可用</td><td>需验证头精度</td><td>可用</td></tr></tbody></table>\n<p>失效条件要写进调度器而不是文档里。第一，γ 固定过大在长上下文下让验证前向的 KV 与算力线性增长，显存被验证占满、吞吐反降，必须按任务统计接受率动态收缩 γ，甚至在接受率跌破阈值时整轮退回朴素解码。第二，拒绝后未正确丢弃被拒位置及其后的草稿 KV，会造成后续轮次 KV 与 token 错位，输出出现重复或乱序——这是草稿验证独有的正确性陷阱，多解码头不存在该路径。第三，草稿与目标量化需分别评估：草稿量化过狠会压低 q 的保真度、拉低接受率，目标量化则改变 p，两者叠加使 min(1,p/q) 的接受判据偏离预期。工程判断落在反馈闭环上：把每轮接受长度、拒绝位置、γ 实际取值打进指标，用滑动窗口接受率驱动 γ 与“是否启用草稿”的开关，让这套机制只在它真能摊薄目标模型权重读取带宽的区间里运行。</p>\n<table class=\"mini\" data-fig=\"alg-quick\"><caption>速查：这一页回答的五件事</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>年份 · 方向</td><td>2022 · 代码投机解码与草稿模型</td></tr><tr><td>解决什么</td><td>代码补全自回归逐 token 解码受内存带宽限制，大模型单步只能出一个 token，低延迟 SLO 下吞吐与首 tok…</td></tr><tr><td>一句话机制</td><td>用小草稿模型快速自回归提出 γ 个候选 token，大目标模型一次前向并行验证并做拒绝采样修正，保证输出分布与目标模型…</td></tr><tr><td>代价与失效</td><td>草稿模型额外占用显存与算力，低接受率时验证开销反成净损失；γ 增大提升理论上限但验证前向的 KV 与算力线性增长，需按任务调参</td></tr><tr><td>后继</td><td>选择性仓库检索</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：algorithms/alg-speculative-decoding-code · 共 8 个片段</p>\n";break;}}})();
